/* The Grounded Readings Library, group geastx (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["geastx"] = [{"id":"eastx-japji-hearing","title":"By Hearing the Name, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["morning","daily","peace"],"text":"By hearing the name of God men become Sidhs, Pirs, Surs, and Naths;\nBy hearing the Name man understandeth the real nature of the earth, its supporting bull, and Heaven;\nBy hearing the Name man obtaineth a knowledge of the continents, the worlds, and the nether regions.\nBy hearing the Name death doth not affect one.\nNanak, the saints are ever happy.\nBy hearing the Name sorrow and sin are no more.\n\nBy hearing the Name man becometh as Shiv, Brahma, and Indar.\nBy hearing the Name even the low become highly lauded.\nBy hearing the Name the way of Jog and the secrets of the body are obtained.\nBy hearing the Name man understandeth the real nature of the Shastars, the Simritis, and the Veds.\nNanak, the saints are ever happy.\nBy hearing the Name sorrow and sin are no more.\n\nBy hearing the Name truth, contentment, and divine knowledge are obtained.\nHearing the Name is equal to bathing at the sixty-eight places of pilgrimage.\nBy hearing the Name and reading it man obtaineth honour.\nBy hearing the Name the mind is composed and fixed on God.\nNanak, the saints are ever happy.\nBy hearing the Name sorrow and sin are no more.\n\nBy hearing the Name, the depth of the sea of virtue is sounded.\nBy hearing the Name men become Shaikhs, Pirs, and Emperors.\nBy hearing the Name a blind man findeth his way.\nBy hearing the Name the unfathomable becometh fathomable.\nNanak, the saints are ever happy.\nBy hearing the Name sorrow and sin are no more.","note":"Pauris eight to eleven of the Japji, the morning prayer every Sikh says at dawn.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 200 to 201","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-obeying","title":"So Pure Is God’s Name, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["morning","daily","peace"],"text":"The condition of him who obeyeth God cannot be described.\nWhoever trieth to describe it, shall afterward repent.\nThere is no paper, or pen, or writer\nTo describe the condition of him who obeyeth God.\nSo pure is His name:\nWhoever obeyeth God knoweth the pleasure of it in his own heart.\n\nBy obeying Him wisdom and understanding enter the mind;\nBy obeying Him man knoweth all worlds;\nBy obeying Him man suffereth not punishment;\nBy obeying Him man shall not depart with Jam.\nSo pure is God’s name:\nWhoever obeyeth God knoweth the pleasure of it in his own heart.\n\nBy obeying Him man’s path is not obstructed;\nBy obeying Him man departeth with honour and distinction;\nBy obeying Him man proceedeth in ecstasy on his way;\nBy obeying Him man formeth an alliance with virtue.\nSo pure is God’s name:\nWhoever obeyeth God knoweth the pleasure of it in his own heart.\n\nBy obeying Him man attaineth the gate of salvation;\nBy obeying Him man is saved with his family;\nBy obeying Him the Guru is saved, and saveth his disciples;\nBy obeying Him, O Nanak, man wandereth not in quest of alms.\nSo pure is God’s name:\nWhoever obeyeth God knoweth the pleasure of it in his own heart.","note":"Pauris twelve to fifteen of the Japji, on the quiet joy of a life that follows God’s will.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 201 to 202","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-numberless","title":"Numberless Thy Worshippers, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","gratitude"],"text":"Numberless thy worshippers, and numberless Thy lovers;\nNumberless Thine adorers, and numberless they who perform austerities for Thee;\nNumberless the reciters of sacred books and Veds;\nNumberless Thy Jogis whose hearts are indifferent to the world;\nNumberless the saints who ponder on Thine attributes and divine knowledge;\nNumberless Thy true men; numberless Thine almsgivers;\nNumberless Thy heroes who face the steel of their enemies;\nNumberless Thy silent worshippers who lovingly fix their thoughts upon Thee.\nWhat power have I to describe Thee?\nSo lowly am I, that I cannot even once be a sacrifice unto Thee.\nWhatever pleaseth Thee is good.\nO Formless One, Thou art ever secure.","note":"Pauri seventeen of the Japji, a song of all the people across the world who love and serve God.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 203 to 204","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-cleansed","title":"Cleansed by the Love of the Name, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["forgiveness","healing","daily"],"text":"When the hands, feet, and other members of the body are covered with filth,\nIt is removed by washing with water.\nWhen thy clothes are polluted,\nApply soap, and the impurity shall be washed away.\nSo when the mind is defiled by sin,\nIt is cleansed by the love of the Name.\nMen do not become saints or sinners by merely calling themselves so.\nThe recording angels take with them a record of man's acts.\nIt is he himself soweth, and he himself eateth.\nNanak, man suffereth transmigration by God’s order.","note":"Pauri twenty of the Japji: as water washes the hands, love of the Name washes the heart.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 205 to 206","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-no-limit","title":"There Is No Limit to God’s Praises, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["gratitude","celebration","daily"],"text":"There is no limit to God’s praises; to those who repeat them there is no limit.\nThere is no limit to His mercy, and to His gifts there is no limit.\nThere is no limit to what God seeth, no limit to what He heareth.\nThe limit of the secret of His heart cannot be known.\nThe limit of His creation cannot be known; neither His near nor His far side can be discovered.\nTo know His limits how many vex their hearts.\nHis limits cannot be ascertained;\nNobody knoweth His limits.\nThe more we say, the more there remains to be said.\nGreat is the Lord, and exalted is His seat.\nHis exalted name is higher than the most exalted.\nWere any one else ever so exalted,\nThen he would know that exalted Being:\nHow great He is He knoweth Himself.\nNanak, God bestoweth gifts on whom He looketh with favour and mercy.","note":"Pauri twenty four of the Japji, on the endless mercy and gifts of God.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 208","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-so-dar","title":"What Is That Gate, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["funeral","hope","celebration"],"text":"What is that gate, what is that mansion where Thou, O God, sittest and watchest over all things?\nHow many various and countless instruments are played!\nHow many musicians!\nHow many musical measures with their consorts, and how many singers sing Thee!\nWind, water, and fire sing Thee; Dharmraj sings at Thy gate.\nThe recording angels, who know how to write, and on whose record Dharmraj judgeth sing Thee.\nIshar, Brahma, and Devi, ever beautiful as adorned by Thee, sing Thee.\nIndar seated on his throne with the gods at Thy gate sing Thee.\nSidhs in meditation sing Thee; holy men in contemplation sing Thee.\nThe continent, the true, and the patient sing Thee; unyielding heroes sing Thee.\nThe pandits and the supreme Rikhis, reading their Veds, sing Thee in every age.\nThe lovely celestial maids who beguile the heart in the upper, middle, and nether regions sing Thee.\nThe jewels created by Thee with the sixty-eight places of Hindu pilgrimage sing Thee.\nMighty warriors and divine heroes sing Thee; the four sources of life sing Thee.\nThe continents, the worlds, and the universe made and supported by Thy hands sing Thee.\nThe saints who please Thee, and who are imbued with Thy love sing Thee.\nThe many others who sing Thee I cannot remember; how could Nanak recount them?","note":"Pauri twenty seven of the Japji: wind, water, fire, saints, and all creation singing at God’s gate. Also sung each evening in Rehras.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 210 to 211","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-strength","title":"I Have No Strength, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["comfort","healing","dying"],"text":"I have no strength to speak and no strength to be silent;\nI have no strength to ask and no strength to give;\nI have no strength to live, and no strength to die;\nI have no strength to acquire empire or wealth which produce a commotion in the heart.\nI have no strength to meditate on Thee or ponder on divine knowledge;\nI have no strength to find the way to escape from the world.\nHe in whose arm there is strength, may see what he can do.\nNanak, no one is of superior or inferior strength before God.","note":"Pauri thirty three of the Japji, an honest prayer for weak days: every strength is God’s.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 214","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-true-mint","title":"The True Mint, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","morning"],"text":"Make continence thy furnace, resignation thy goldsmith,\nUnderstanding thine anvil, divine knowledge thy tools,\nThe fear of God thy bellows, austerities thy fire.\nDivine love thy crucible, and melt God’s name therein.\nIn such a true mint the Word shall be coined.\nThis is the practice of those on whom God looketh with an eye of favour.\nNanak, the Kind One by a glance maketh them happy.","note":"Pauri thirty eight of the Japji: a life of patience, wisdom, and love becomes the forge where the Word is shaped.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 217","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-japji-slok","title":"The Air Is the Guru, the Closing Slok of the Japji","by":"Guru Angad (traditionally), closing the Japji","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["funeral","nature","hope","morning"],"text":"The air is the guru, water our father, and the great earth our mother;\nDay and night are our two nurses, male and female, who set the whole world a-playing.\nMerits and demerits shall be read out in the presence of the Judge.\nAccording to men’s acts, some shall be near, and others distant from God.\nThey who have pondered on the Name and departed after the completion of their toil,\nShall have their countenances made bright, O Nanak; how many shall be emancipated in company with them!","note":"The closing verse of the Japji, also said at the end of a Sikh funeral: air, water, earth, day, and night as our family.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 217","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-rehras-call-thee-great","title":"As Men Have Heard, So All Call Thee Great, from Rehras","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","gratitude"],"text":"As men have heard so all call Thee great;\nBut hath any one ever seen how great Thou art?\nThy worth cannot be estimated or described;\nThey who seek to describe it are absorbed in Thee.\nO my great Lord, deep and profound, brimful of excellences.\nNone knoweth the extent of Thine outline.\nThough all meditative men were to meet and meditate upon Thee,\nThough all appraisers were to meet and appraise Thee,\nThey who possess divine and spiritual wisdom, priests and high priests,\nYet they could not describe even a small portion of Thy greatness.\nAll truth, all fervour, all goodness,\nThe excellences of perfect men,\nCannot be obtained in their perfection without Thee.\nIf Thy grace be obtained none can be excluded;\nOf what account is the helpless speaker?\nThy storerooms are filled with Thy praises.\nWho can prevail against him to whom Thou givest?\nNanak, the True One arrangeth all.","note":"A hymn of Guru Nanak sung in Rehras, the Sikh evening prayer at sunset.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 251 to 252","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-rehras-repeat-name","title":"If I Repeat the Name, I Live, from Rehras","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","daily","comfort"],"text":"If I repeat the Name, I live; if I forget it, I die;\nIt is difficult to repeat the true Name.\nIf man hunger after the true Name,\nHis pain shall depart when he satisfieth himself with it.\nThen how could I forget it, O my mother?\nTrue is the Lord, true is His name.\nMen have grown weary of uttering\nEven an iota of His greatness; His worth they have not discovered.\nIf all men joined and tried to describe Him,\nThat would not add to or detract from His greatness.\nGod dieth not, neither is there any mourning for Him;\nHe continueth to give us our daily bread which never faileth.\nHis praise is that there neither is,\nNor was, nor shall be any one like unto Him.\nAs great as Thou art Thyself, O God, so great are Thy gifts.\nThou who madest the day madest also the night.\nThey who forget their Spouse are evil persons: Nanak, without His name they are naught.","note":"Guru Nanak’s hymn on the Name as the breath of life, sung each evening in Rehras.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 252","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-rehras-kulang","title":"Why Art Thou Afraid?, from Rehras","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["comfort","hope","evening"],"text":"O my soul, why proposest thou exertion when God Himself is engaged in effort for thee?\nHe even putteth their food before the insects which He created in rocks and stones.\nO my God, they who meet the society of the saints are saved.\nThrough the favour of the Guru they obtain the highest rank; though they be as dry wood, they are made green.\nNo one can rely on mother, father, friends, children, or wives.\nGod provideth every one with his daily food; why, O man, art thou afraid?\nThe kulang flieth away hundreds of miles, leaving her young behind her.\nWho feedeth them? Who giveth them morsels to peck at? Have you not considered this?\nGod holdeth in the palm of His hand all treasures and the eighteen supernatural powers.\nNanak is ever a sacrifice unto Thee; O God, Thou hast no end or bounds.","note":"Guru Arjan’s hymn of trust, sung in Rehras: as the crane’s young are fed far from her, God provides for every life.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 253 to 254","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-rehras-so-purukh","title":"That Being Is Pure, from Rehras","by":"Guru Ram Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","peace","comfort"],"text":"That Being is pure, God is the pure Being, God is altogether inaccessible and illimitable.\nAll meditate on Thee; all meditate on Thee; O God, Thou art the true Creator.\nAll creatures are Thine; Thou providest for them all.\nO saints, meditate on God who causeth all misery to be forgotten.\nGod Himself is the Lord, God Himself is the worshipper; Nanak, what a helpless creature is man!\nThou, O God, the one Supreme Being, art fully contained in every heart and pervadest everything.\nSome men are givers, some beggars; all are Thy wondrous sport.\nThou Thyself art the Giver; Thou art the Enjoyer; I know none beside Thee.\nThou art the totally infinite Supreme Being; what attributes of Thine shall I recount?\nThe slave Nanak is a sacrifice unto those who serve Thee, unto those who serve Thee.\nThey who meditate on Thee, who meditate on Thee, O God, abide in happiness in this age.\nThey who meditate on God are emancipated, are emancipated, my friend; for them Death’s noose is broken.\nAll fear hath departed from those who have meditated on the fearless, the fearless God.\nThey who have worshipped, who have worshipped my God, are absorbed in Him.\nBlest, blest are they who have meditated on God; the slave Nanak will become a sacrifice unto them.","note":"The opening of So Purkh, Guru Ram Das’s hymn in Rehras: all fear departs from those who rest in the fearless God.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 254 to 255","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sohila-song-of-joy","title":"Sing the Sohila, the First Hymn of Sohila","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["funeral","dying","evening"],"text":"In the house in which God’s praise is sung and He is meditated on,\nSing the Sohila and remember the Creator.\nSing the Sohila of my Fearless Lord; I am a sacrifice to that song of joy by which everlasting comfort is obtained.\nEver and ever living things are watched over; the Giver regardeth their wants.\nWhen even Thy gifts cannot be appraised, who can appraise the Giver?\nThe year and the auspicious time for marriage are recorded; relations meet and pour oil on me the bride.\nO my friends, pray for me that I may meet my Lord.\nThis message is ever sent to every house: such invitations are ever issued.\nRemember the Caller; Nanak, the day is approaching.","note":"The first hymn of Kirtan Sohila, sung at bedtime and at a Sikh funeral: the soul as a bride going home to the Beloved.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Sohila, p. 258","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sohila-arti","title":"The Sun and Moon Are Thy Lamps, the Arti of Guru Nanak","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["nature","evening","gratitude","peace"],"text":"The sun and moon, O Lord, are Thy lamps; the firmament Thy salver; the orbs of the stars the pearls enchased in it.\nThe perfume of the sandal is Thine incense, the wind is Thy fan, all the forests are Thy flowers, O Lord of light.\nWhat worship is this, O Thou Destroyer of birth? Unbeaten strains of ecstasy are the trumpets of Thy worship.\nThou hast a thousand eyes and yet not one eye; Thou hast a thousand forms and yet not one form;\nThou hast a thousand stainless feet and yet not one foot; Thou hast a thousand organs of smell and yet not one organ. I am fascinated by this play of Thine.\nThe light which is in everything is Thine, O Lord of light.\nFrom its brilliancy everything is brilliant;\nBy the Guru’s teaching the light becometh manifest.\nWhat pleaseth Thee is the real worship.\nO God, my mind is fascinated with Thy lotus feet as the bumble-bee with the flower: night and day I thirst for them.\nGive the water of Thy favour to the sarang (the rain bird) Nanak, so that he may dwell in Thy name.","note":"Guru Nanak’s Arti from Kirtan Sohila: the whole sky as a worship tray, sung at evening and loved across faiths.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Sohila, p. 259","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sohila-serve-saints","title":"It Is Time to Serve the Saints, from Sohila","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","dying","hope"],"text":"I pray you hear me, my friends, it is time to serve the saints.\nEarn here the profit of God’s name, and in the next world ye shall abide in happiness.\nHuman life groweth shorter every day and night;\nO man, meet the Guru and arrange thine affairs.\nThis world is involved in wickedness and superstition; they who know God are saved.\nHe whom God awakeneth and causeth to drink the essence of His word, knoweth the story of the Ineffable.\nPurchase that for which thou hast come into the world, and God by the Guru’s favour will dwell in thy heart.\nThou shalt find a home with comfort and peace in God’s own palace, and not return again to this world.\nO God, Searcher of hearts, Arranger, fulfil the desires of my heart.\nThe slave Nanak craveth the happiness of being made the dust of the saints’ feet.","note":"The closing hymn of Kirtan Sohila, sung at night and at the end of a life: a home with comfort and peace in God’s own palace.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Sohila, p. 260","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sukhmani-remember","title":"Remember, Remember God, the Opening of the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["morning","peace","daily"],"text":"I bow to the primal Guru;\nI bow to the Guru of the primal age;\nI bow to the true Guru;\nI bow to the holy divine Guru.\n\nRemember, remember God; by remembering Him you shall obtain happiness,\nAnd erase from your hearts trouble and affliction.\nRemember the praises of the one all-supporting God.\nNumberless persons utter God's various names.\nInvestigating the Veds, the Purans, and the Simritis,\nMen have made out the one word which is God's name.\nHis praises cannot be recounted,\nWho treasureth God's name in his heart even for a moment.\nSaith Nanak, save me, Lord, with those who are desirous of one glance of Thee.\nIn this Sukhmani is the name of God which like ambrosia bestoweth happiness.\nAnd giveth peace to the hearts of the saints.","note":"The opening of the Sukhmani, the Psalm of Peace, said in the morning by many Sikhs after the Japji.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 197 to 198","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sukhmani-remembering","title":"By Remembering God, from the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["comfort","peace","healing"],"text":"By remembering God man doth not again enter the womb;\nBy remembering God the tortures of Death disappear;\nBy remembering God death is removed;\nBy remembering God enemies retreat;\nBy remembering God no obstacles are met;\nBy remembering God we are watchful night and day;\nBy remembering God fear is not felt;\nBy remembering God sorrow troubleth not:\nMen remember God in the company of the saints;\nNanak, by the love of God all wealth is obtained.\n\nBy remembering God everything is accomplished;\nBy remembering God man never grieveth;\nBy remembering God man uttereth His praises;\nBy remembering God man is easily absorbed in Him;\nBy remembering God man findeth an immovable seat;\nBy remembering God the lotus of man's heart bloometh;\nBy remembering God man heareth the unbeaten melody;\nThe happiness which is obtained by remembering God hath no end or limit:\nThey to whom God is merciful remember Him;\nNanak seeketh the protection of such men.","note":"From the first ashtapadi of the Sukhmani: remembrance of God takes away fear and sorrow.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 198 to 200","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sukhmani-name-with-thee","title":"The Name Shall Go with Thee, from the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["dying","funeral","comfort"],"text":"Where man hath neither mother, nor father, nor son, nor friend, nor brother,\nThere, O my soul, God's name shall be with thee and assist thee.\nWhere the very terrible ministers of Death crush thee,\nThere the name of God alone shall go with thee.\nWhere there are very great obstacles,\nThe name of God will remove them in a moment.\nThou shalt not be saved even by many expiations;\nIt is the name of God which removeth millions of sins.\nO my soul, utter the name of God under the Guru's instruction;\nThus shalt thou, saith Nanak, have manifold joys.\n\nThe king of the whole world is miserable;\nOnly he is happy who uttereth God's name.\nEven though there be millions of entanglements,\nBy uttering the name of God, we shall be freed from them all.\nThe various pleasures of the world allay not our thirst,\nBut by pondering on God's name it is quenched.\nOn the road on which man goeth alone,\nThe name of God is with him to cheer him.\nEver ponder on such a Name in thy heart,\nAnd under the Guru's instruction, Nanak, thou shalt obtain the supreme state.\n\nOn the way where the miles cannot be counted,\nThe name of God shall there be thy provision;\nOn the way where there is pitch darkness,\nThe name of God shall accompany and light thee;\nOn the way where nobody knoweth thee,\nThe name of God shall be there to recognize thee;\nWhere there is very terrible heat and great sunshine,\nThere the name of God shall be a shadow over thee.\nO man, where thirst tormenteth thee,\nThere, saith Nanak, the name of God shall rain nectar on thee.","note":"From the second ashtapadi of the Sukhmani, read beside the dying and at a Sikh funeral: on the long road ahead, the Name is provision, light, and shade.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 201 to 202","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sukhmani-knoweth-god","title":"The Man Who Knoweth God, from the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["funeral","daily","peace"],"text":"He whose heart is true and whose words are true\nLooketh at nobody but the one God.\nNanak, these are the marks of a man who knoweth God:\n\nThe man who knoweth God is ever uncontaminated,\nAs the lotus is untouched by the water;\nThe man who knoweth God is ever stainless,\nAs all things purified by the sun;\nThe man who knoweth God looketh on all men as equal,\nAs the wind bloweth on the rich and poor alike;\nThe man who knoweth God is uniformly patient,\nLike the earth which one man diggeth up and another smeareth with sandal.\nThis is the attribute of the man who knoweth God;\nNanak, his nature is like that of fire.\n\nThe man who knoweth God is the purest of the pure,\nAs filth cannot permanently attach to water;\nThe mind of the man who knoweth God is enlightened,\nLike the firmament above the earth;\nTo the man who knoweth God a friend and foe are the same;\nThe man who knoweth God hath no pride;\nThe man who knoweth God is the most exalted of the exalted;\nYet his mind is the most humble of all;\nNanak, only those are Brahmgyanis\nWhom God Himself maketh so.\n\nThe man who knoweth God loveth Him alone;\nGod abideth with the man who knoweth Him;\nThe Name is the support of the man who knoweth God,\nThe Name is a halo for the man who knoweth God;\nThe man who knoweth God is ever watchful,\nThe man who knoweth God renounceth pride,\nThe heart of him who knoweth God feeleth supreme delight,\nThe home of him who knoweth God is ever happy,\nThe man who knoweth God dwelleth in peace and rest,\nThe man who knoweth God, Nanak, shall never perish.","note":"From the eighth ashtapadi of the Sukhmani, on the one who knows God: humble as dust, patient as the earth, kind to all. Often read to honor a life well lived.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 221 to 223","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-anand-joy","title":"Joy, My Mother, the Opening of the Anand","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["wedding","celebration","birth","gratitude"],"text":"Joy, my mother, that I have found the True Guru!\nI have easily found the True Guru, and the music of gratulation is in my heart.\nThe excellent Rags and the race of the female singers of heaven have come to sing hymns.\nThey who have fixed God in their hearts sing His praises.\nSaith Nanak, I feel joy that I have obtained the True Guru.\n\nO my soul, ever abide with God;\nAbide with God, O my soul; He will make thee forget all sorrow;\nHe will accept thee, and arrange all thine affairs.\nThe Lord is omnipotent in all things; why forget Him?\nSaith Nanak, O my soul, ever abide with God.\n\nO my true Lord, what is there not in Thy house?\nIn Thy house is everything; he to whom Thou givest shall receive;\nHe will ever praise Thine attributes and plant Thy name in his heart.\nMany strains of rejoicing resound for him in whose heart Thy name abideth.\nSaith Nanak, O true Lord, what is there not in Thy house?\n\nThe true Name is my support;\nThe true Name which satisfieth all my hunger, is my support.\nGod's name having entered my heart hath granted me peace and happiness, and fulfilled all my desires.\nI have ever sacrificed myself to the Guru who possesseth such excellences.\nSaith Nanak, hear, O saints, love God's hymns: The true Name is my support.\n\nThe five forms of music resound in that happy house;\nIn that happy house into which God hath infused His might, the strains resound.\nThou, O God, hast put the five evil passions under subjection, and vanquished Death the torturer.\nThey who were so predestined are attached to Thy name, O God.\nSaith Nanak, they obtain happiness, and in their hearts the unbeaten strain resoundeth.","note":"The first five pauris of the Anand, the Song of Joy, sung at every Anand Karaj wedding, at a birth, and at the close of Sikh services.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), the Anand, p. 117 to 119","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-anand-eyes-ears","title":"O Eyes of Mine, O Ears of Mine, from the Anand","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["daily","nature","gratitude"],"text":"O eyes of mine, God infused light into you, look at none but God;\nLook at none but God; look on Him intently.\nAll this world which you behold is God's image; God's image appeareth in it.\nWhen by the Guru's favour I received understanding, I saw that God was one, and that there was none besides.\nSaith Nanak, these eyes were blind, but on meeting the true Guru they obtained divine light.\n\nO ears of mine, you were sent to hear the truth;\nYou were sent and attached to this body to hear the truth; hear the true Word,\nBy hearing which the soul and body are revived, and the tongue absorbed in God's relish.\nThe True One is invisible and wonderful; His state cannot be described.\nSaith Nanak, hear the ambrosial Name and you shall be pure; you were sent to hear the truth.\n\nGod having put the soul into the cave of the body, blew breath into it as a musical instrument;\nHe blew breath into it as a musical instrument; nine doors of the body He disclosed, and the tenth He concealed;\nTo some through the Guru He gave faith and disclosed the tenth door:\nThere are the various forms of God, there the nine treasures of His name, but His end is never found.\nSaith Nanak, the beloved God having put the soul into the cave of the body, blew breath into it as a musical instrument.","note":"Pauris thirty six to thirty eight of the Anand: all the world is God’s image, and the body is an instrument God plays with breath.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), the Anand, p. 128 to 129","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-anand-closing","title":"Listen to My Joy, the Closing Pauri of the Anand","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["celebration","wedding","gratitude","hope"],"text":"Sing this true song of rejoicing in the true temple;\nSing this song of rejoicing in the true temple where the saints ever meditate on the True One.\nThey who please Thee and to whom Thou givest understanding through the Guru's instruction, meditate on Thee, O True One.\nThe True One is the Lord of all; he on whom He bestoweth favours shall receive Him.\nSaith Nanak, sing this true song of rejoicing in the true temple.\n\nListen to my joy, my very fortunate friends, all my desires have been fulfilled:\nI have obtained God the Supreme Brahm, and all my sorrows have departed;\nMy sorrows, mine afflictions, and my sufferings have departed by listening to the true Word.\nThe saints and holy men are happy on hearing it from the perfect Guru:\nPure are they who hear it, stainless those who utter it, the true Guru will fill their hearts!\nNanak representeth, for those who attached themselves to the Guru's feet the unblown trumpets play.","note":"The last two pauris of the Anand, the joyful close of Sikh weddings and gatherings.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), the Anand, p. 129","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-anand-ever-remember","title":"As Thou Causest Us to Walk, from the Anand","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["comfort","grief","daily"],"text":"O dear man, do thou ever remember the True One.\nThis family which thou seest shall not depart with thee;\nIt shall not depart with thee; why fix thy thoughts thereon?\nNever do what thou shalt have to repent of at last.\nHearken to the instruction of the true Guru; it is that which shall go with thee.\nSaith Nanak, O dear man, ever remember the True One.\n\nAs thou causest us, O Lord, to walk, so we walk; what more can we know of Thine attributes?\nThey whom Thou hast put on the right way walk as Thou causest them;\nThey whom Thou of Thy mercy appliest to Thy name ever meditate on Thee, O God;\nThey to whom Thou impartest Thine instruction through the Guru shall obtain happiness.\nSaith Nanak, O true Lord, Thou causest us to walk as Thou pleasest.","note":"Pauris eleven and fifteen of the Anand: remember the True One, who guides each step of the way.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), the Anand, p. 118, 120","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-zor-soul-dawn","title":"At the Dawn of the Fourth Day, from the Hadokht Nask","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"scripture","occasion":["funeral","dying","grief","hope"],"text":"Zarathustra asked Ahura Mazda: ‘O Ahura Mazda, most beneficent Spirit, Maker of the material world, thou Holy One!\n\n‘When one of the faithful departs this life, where does his soul abide on that night?’\n\nAhura Mazda answered:\n\n‘It takes its seat near the head, singing the Ustavaiti Gatha and proclaiming happiness: “Happy is he, happy the man, whoever he be, to whom Ahura Mazda gives the full accomplishment of his wishes!” On that night his soul tastes as much of pleasure as the whole of the living world can taste.’\n\nAt the end of the third night, when the dawn appears, it seems to the soul of the faithful one as if it were brought amidst plants and scents: it seems as if a wind were blowing from the region of the south, from the regions of the south, a sweet-scented wind, sweeter-scented than any other wind in the world.\n\nAnd it seems to the soul of the faithful one as if he were inhaling that wind with the nostrils, and he thinks: ‘Whence does that wind blow, the sweetest-scented wind I ever inhaled with my nostrils?’\n\nAnd it seems to him as if his own conscience were advancing to him in that wind, in the shape of a maiden fair, bright, white-armed, strong, tall-formed, high-standing, beautiful of body, noble, . . . as fair as the fairest things in the world.\n\nAnd the soul of the faithful one addressed her, asking: ‘What maid art thou, who art the fairest maid I have ever seen?’\n\nAnd she, being his own conscience, answers him: ‘O thou youth of good thoughts, good words, and good deeds, of good religion, I am thy own conscience!\n\n‘I was lovely and thou madest me still lovelier; I was fair and thou madest me still fairer; I was desirable and thou madest me still more desirable; I was sitting in a forward place and thou madest me sit in the foremost place, through this good thought, through this good speech, through this good deed of thine; and so henceforth men worship me for my having long sacrificed unto and conversed with Ahura Mazda.\n\n‘The first step that the soul of the faithful man made, placed him in the Good-Thought Paradise;\n\n‘The second step that the soul of the faithful man made, placed him in the Good-Word Paradise;\n\n‘The third step that the soul of the faithful man made, placed him in the Good-Deed Paradise;\n\n‘The fourth step that the soul of the faithful man made, placed him in the Endless Lights.’","note":"From Yasht 22: on the third night after death the soul of a good person meets its own conscience, fair as the fairest things in the world, and walks in four steps into the Endless Lights. Read during the Zoroastrian days of mourning.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Yasht 22, p. 314 to 317","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-zor-sun-nyayis","title":"Hail unto the Sun, from the Khorshed Nyayis","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"prayer","occasion":["morning","daily","gratitude"],"text":"Hail unto thee, O Ahura Mazda, in the threefold way! [Hail unto thee] before all other creatures!\n\nHail unto you, O Amesha-Spentas, who are all of you of one accord with the Sun!\n\nMay this prayer come unto Ahura Mazda! May it come unto the Amesha-Spentas! May it come unto the Fravashis of the holy Ones! May it come unto the Sovereign Vayu of the long Period!\n\nI praise well-thought, well-spoken, and well-done thoughts, words, and deeds. I embrace all good thoughts, good words, and good deeds; I reject all evil thoughts, evil words, and evil deeds.\n\nI give sacrifice and prayer unto you, O Amesha-Spentas! even with the fulness of my thoughts, of my words, of my deeds, and of my heart: I give unto you even my own life.\n\nMay I grow in health of body through Vohu-Mano, Khshathra, and Asha, and come to that luminous space, to that highest of all high things, when the world, O Spenta Mainyu! has come to an end!\n\nWe sacrifice unto the bright, undying, shining, swift-horsed Sun.","note":"From the prayer to the Sun, said by Zoroastrians at sunrise, noon, and afternoon: good thoughts, good words, good deeds, and the hope of the luminous space.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Khorshed Nyayis, p. 350 to 351","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-zor-atash-blessing","title":"Mayest Thou Burn in This House, from the Atash Nyayis","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"blessing","occasion":["home","blessing","daily"],"text":"Mayest thou burn in this house! Mayest thou ever burn in this house! Mayest thou blaze in this house! Mayest thou increase in this house! Even for a long time, till the powerful restoration of the world, till the time of the good, powerful restoration of the world!\n\nGive me, O Atar, son of Ahura Mazda! however unworthy I am, now and for ever, a seat in the bright, all-happy, blissful abode of the holy Ones.\n\nMay I obtain the good reward, a good renown, and long cheerfulness for my soul!\n\n‘May herds of oxen grow for thee, and increase of sons; may thy mind be master of its vow, may thy soul be master of its vow, and mayest thou live on in the joy of the soul all the nights of thy life.’","note":"From the prayer to the sacred Fire, said in its presence: a blessing on the hearth, the home, and the soul.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Atash Nyayis, p. 359 to 361","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-zor-airyaman","title":"The Airyaman Prayer, Yasna 54","by":"Traditional, the Avesta","tr":"Lawrence Heyworth Mills","year":1887,"trad":["zoroastrian"],"type":"prayer","occasion":["wedding","blessing","celebration"],"text":"Let the Airyaman, the desired friend and peersman, draw near for grace to the men and to the women who are taught of Zarathustra, for the joyful grace of the Good Mind, whereby the conscience may attain its wished-for recompense. I pray for the sacred reward of the ritual order which is (likewise so much) to be desired; and may Ahura Mazda grant it, (or cause it to increase).","note":"The Airyema Ishyo, one of the holiest Zoroastrian prayers, said at weddings and for the gathered community.","voice":"brian","source":{"name":"The Zend-Avesta, part 3, tr. L. H. Mills, Sacred Books of the East vol. 31 (1887), Yasna 54, p. 294","url":"https://archive.org/details/wg931"},"rights":"pd","pd":"published 1887; Mills died 1918","denom":[]},{"id":"eastx-zor-this-i-ask","title":"This I Ask Thee, O Ahura, from Yasna 44","by":"Zarathushtra, the Gathas","tr":"Lawrence Heyworth Mills","year":1887,"trad":["zoroastrian"],"type":"scripture","occasion":["nature","daily","gratitude"],"text":"This I ask Thee, O Ahura! tell me aright: Who by generation was the first father of the Righteous Order (within the world)? Who gave the (recurring) sun and stars their (undeviating) way? Who established that whereby the moon waxes, and whereby she wanes, save Thee? These things, O Great Creator! would I know, and others likewise still.\n\nThis I ask Thee, O Ahura! tell me aright, who from beneath hath sustained the earth and the clouds above that they do not fall? Who made the waters and the plants? Who to the wind has yoked on the storm-clouds, the swift and fleetest two? Who, O Great Creator! is the inspirer of the good thoughts (within our souls)?\n\nThis I ask Thee, O Ahura! tell me aright; who, as a skilful artisan, hath made the lights and the darkness? Who, as thus skilful, hath made sleep and the zest (of waking hours)? Who (spread) the Auroras, the noontides and midnight, monitors to discerning (man), duty’s true (guides)?","note":"From the Gathas, Zarathushtra’s own hymns: a song of wonder at the sun, stars, moon, waters, plants, and the good thoughts within us.","voice":"brian","source":{"name":"The Zend-Avesta, part 3, tr. L. H. Mills, Sacred Books of the East vol. 31 (1887), Yasna 44, p. 113 to 114","url":"https://archive.org/details/wg931"},"rights":"pd","pd":"published 1887; Mills died 1918","denom":[]},{"id":"eastx-zor-moon","title":"Hail to Thee When We Look at Thee, from the Mah Yasht","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"prayer","occasion":["nature","evening","season"],"text":"Hail to Ahura Mazda! Hail to the Amesha-Spentas! Hail to the Moon that keeps in it the seed of the Bull! Hail to thee when we look at thee! Hail to thee when thou lookest at us!\n\nHow does the moon wax? How does the moon wane?\n\nFor fifteen days does the moon wax; for fifteen days does the moon wane. As long as her waxing, so long is the waning; as long as her waning, so long is the waxing.\n\n‘Who is there but thee who makes the moon wax and wane?’\n\nWe sacrifice unto the Moon that keeps in it the seed of the Bull, the holy and master of holiness.\n\nHere I look at the moon, here I perceive the moon; here I look at the light of the moon, here I perceive the light of the moon. The Amesha-Spentas stand up, holding its glory; the Amesha-Spentas stand up, pouring its glory upon the earth, made by Mazda.\n\nAnd when the light of the moon waxes warmer, golden-hued plants grow on from the earth during the spring.","note":"From the hymn to the Moon, said by Zoroastrians at the new moon, the full moon, and the waning: a prayer of wonder at the light that tends the growing earth.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Mah Yasht, p. 88 to 90","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-metta-sutta","title":"The Metta Sutta, Goodwill Towards All Beings","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["daily","peace","blessing","healing"],"text":"Whatever is to be done by one who is skilful in seeking (what is) good, having attained that tranquil state (of Nibbana): Let him be able and upright and conscientious and of soft speech, gentle, not proud,\n\nAnd contented and easily supported and having few cares, unburdened and with his senses calmed and wise, not arrogant, without (showing) greediness (when going his round) in families.\n\nAnd let him not do anything mean for which others who are wise might reprove (him); may all beings be happy and secure, may they be happy-minded.\n\nWhatever living beings there are, either feeble or strong, all either long or great, middle-sized, short, small or large,\n\nEither seen or which are not seen, and which live far (or) near, either born or seeking birth, may all creatures be happy-minded.\n\nLet no one deceive another, let him not despise (another) in any place, let him not out of anger or resentment wish harm to another.\n\nAs a mother at the risk of her life watches over her own child, her only child, so also let every one cultivate a boundless (friendly) mind towards all beings.\n\nAnd let him cultivate goodwill towards all the world, a boundless (friendly) mind, above and below and across, unobstructed, without hatred, without enmity.\n\nStanding, walking or sitting or lying, as long as he be awake, let him devote himself to this mind; this (way of) living they say is the best in this world.\n\nHe who, not having embraced (philosophical) views, is virtuous, endowed with (perfect) vision, after subduing greediness for sensual pleasures, will never again go to a mother’s womb.","note":"The Buddha’s discourse on loving-kindness, chanted daily in Theravada homes and temples and at every Buddhist blessing.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Mettasutta, p. 24 to 25","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-mangala-sutta","title":"The Highest Blessing, the Mangala Sutta","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["blessing","wedding","daily","home","celebration"],"text":"So it was heard by me:\n\nAt one time Bhagavat dwelt at Savatthi, in Cetavana, in the park of Anathapindika. Then, when the night had gone, a deity of beautiful appearance, having illuminated the whole Cetavana, approached Bhagavat, and having approached and saluted him, he stood apart, and standing apart that deity addressed Bhagavat in a stanza:\n\n‘Many gods and men have devised blessings, longing for happiness, tell thou (me) the highest blessing.’\n\nBuddha said: ‘Not cultivating (the society of) fools, but cultivating (the society of) wise men, worshipping those that are to be worshipped, this is the highest blessing.\n\n‘To live in a suitable country, to have done good deeds in a former (existence), and a thorough study of one’s self, this is the highest blessing.\n\n‘Great learning and skill, well-learnt discipline, and well-spoken words, this is the highest blessing.\n\n‘Waiting on mother and father, protecting child and wife, and a quiet calling, this is the highest blessing.\n\n‘Giving alms, living religiously, protecting relatives, blameless deeds, this is the highest blessing.\n\n‘Ceasing and abstaining from sin, refraining from intoxicating drink, perseverance in the Dhammas, this is the highest blessing.\n\n‘Reverence and humility, contentment and gratitude, the hearing of the Dhamma at due seasons, this is the highest blessing.\n\n‘Patience and pleasant speech, intercourse with Samanas, religious conversation at due seasons, this is the highest blessing.\n\n‘Penance and chastity, discernment of the noble truths, and the realisation of Nibbana, this is the highest blessing.\n\n‘He whose mind is not shaken (when he is) touched by the things of the world (lokadhamma), (but remains) free from sorrow, free from defilement, and secure, this is the highest blessing.\n\n‘Those who, having done such (things), are undefeated in every respect, walk in safety everywhere, theirs is the highest blessing.’","note":"The Buddha’s teaching on the highest blessings of a good life, chanted at Theravada weddings, house blessings, and new beginnings.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Mahamangalasutta, p. 43 to 44","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-salla-sutta","title":"As the Wind Blows a Tuft of Cotton, from the Salla Sutta","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["grief","funeral","comfort"],"text":"Without a cause and unknown is the life of mortals in this world, troubled and brief, and combined with pain.\n\nFor there is not any means by which those that have been born can avoid dying; after reaching old age there is death, of such a nature are living beings.\n\nAs ripe fruits are early in danger of falling, so mortals when born are always in danger of death.\n\nAs all earthen vessels made by the potter end in being broken, so is the life of mortals.\n\nEven if a man lives a hundred years or even more, he is at last separated from the company of his relatives, and leaves life in this world.\n\nAs a house on fire is extinguished by water, so also the wise, sensible, learned, clever man rapidly drives away sorrow that has arisen, as the wind a tuft of cotton.","note":"From the Buddha’s discourse on grief, chanted at Theravada funerals: life is brief, and peace comes as the arrow of sorrow is gently drawn out.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Sallasutta, p. 106 to 108","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-heart-sutra","title":"The Heart Sutra","by":"Traditional, the Prajnaparamita","tr":"F. Max Muller","year":1894,"trad":["buddhist"],"denom":["mahayana"],"type":"scripture","occasion":["funeral","peace","daily"],"text":"Adoration to the Omniscient!\n\nThe venerable Bodhisattva Avalokitesvara, performing his study in the deep Pragnaparamita (perfection of wisdom), thought thus: ‘There are the five Skandhas, and these he considered as by their nature empty (phenomenal).’\n\n‘O Sariputra,’ he said, ‘form here is emptiness, and emptiness indeed is form. Emptiness is not different from form, form is not different from emptiness. What is form that is emptiness, what is emptiness that is form.’\n\n‘The same applies to perception, name, conception, and knowledge.’\n\n‘Here, O Sariputra, all things have the character of emptiness, they have no beginning, no end, they are faultless and not faultless, they are not imperfect and not perfect. Therefore, O Sariputra, in this emptiness there is no form, no perception, no name, no concepts, no knowledge. No eye, ear, nose, tongue, body, mind. No form, sound, smell, taste, touch, objects.’\n\n‘There is no knowledge, no ignorance, no destruction of knowledge, no destruction of ignorance,’ &c., till we come to ‘there is no decay and death, no destruction of decay and death; there are not (the four truths, viz. that there) is pain, origin of pain, stoppage of pain, and the path to it. There is no knowledge, no obtaining (of Nirvana).’\n\n‘A man who has approached the Pragnaparamita of the Bodhisattva dwells enveloped in consciousness. But when the envelopment of consciousness has been annihilated, then he becomes free of all fear, beyond the reach of change, enjoying final Nirvana.’\n\n‘All Buddhas of the past, present, and future, after approaching the Pragnaparamita, have awoke to the highest perfect knowledge.’\n\n‘Therefore one ought to know the great verse of the Pragnaparamita, the verse of the great wisdom, the unsurpassed verse, the peerless verse, which appeases all pain, it is truth, because it is not false, the verse proclaimed in the Pragnaparamita: “O wisdom, gone, gone, gone to the other shore, landed at the other shore, Svaha!”’","note":"The Heart of the Perfection of Wisdom, chanted daily in Zen, Tibetan, and other Mahayana temples and at Buddhist funerals: form is emptiness, and the mind beyond fear.","voice":"brian","source":{"name":"Buddhist Mahayana Texts, tr. F. Max Muller, Sacred Books of the East vol. 49 (1894), The Smaller Pragna-paramita-hridaya-sutra, p. 153 to 154","url":"https://archive.org/details/buddhistmahy02cowe"},"rights":"pd","pd":"published 1894; Muller died 1900"},{"id":"eastx-pure-land-amitayus","title":"Immeasurable Life and Light, from the Smaller Sukhavati-vyuha","by":"Traditional, the Pure Land sutras","tr":"F. Max Muller","year":1894,"trad":["buddhist"],"denom":["mahayana","pureland"],"type":"scripture","occasion":["dying","funeral","hope","comfort"],"text":"‘Now what do you think, O Sariputra, for what reason is that Tathagata called Amitayus? The length of life (ayus), O Sariputra, of that Tathagata and of those men there is immeasurable (amita). Therefore is that Tathagata called Amitayus. And ten kalpas have passed, O Sariputra, since that Tathagata awoke to perfect knowledge.\n\n‘And what do you think, O Sariputra, for what reason is that Tathagata called Amitabha? The splendour (abha), O Sariputra, of that Tathagata is unimpeded over all Buddha countries. Therefore is that Tathagata called Amitabha.\n\n‘Then again all beings, O Sariputra, ought to make fervent prayer for that Buddha country. And why? Because they come together there with such excellent men. Beings are not born in that Buddha country of the Tathagata Amitayus as a reward and result of good works performed in this present life. No, whatever son or daughter of a family shall hear the name of the blessed Amitayus, the Tathagata, and having heard It, shall keep It In mind, and with thoughts undisturbed shall keep It In mind for one, two, three, four, five, six or seven nights, when that son or daughter of a family comes to die, then that Amitayus, the Tathagata, surrounded by an assembly of disciples and followed by a host of Bodhisattvas, will stand before them at their hour of death, and they will depart this life with tranquil minds. After their death they will be born In the world Sukhavati, In the Buddha country of the same Amitayus, the Tathagata. Therefore, then, O Sariputra, having perceived this cause and effect, I with reverence say thus. Every son and every daughter of a family ought with their whole mind to make fervent prayer for that Buddha country,","note":"From the Smaller Sukhavati-vyuha, the heart of Pure Land Buddhism: those who keep the name of the Buddha of Immeasurable Life in mind depart this life with tranquil minds. Read beside the dying and at Pure Land funerals.","voice":"brian","source":{"name":"Buddhist Mahayana Texts, tr. F. Max Muller, Sacred Books of the East vol. 49 (1894), The Smaller Sukhavati-vyuha, p. 97 to 99","url":"https://archive.org/details/buddhistmahy02cowe"},"rights":"pd","pd":"published 1894; Muller died 1900"},{"id":"eastx-diamond-sutra-dream","title":"Like a Dream, a Bubble, a Shadow, the Close of the Diamond Sutra","by":"Traditional, the Diamond Sutra","tr":"William Gemmell","year":1912,"trad":["buddhist"],"denom":["mahayana","zen"],"type":"scripture","occasion":["funeral","grief","peace"],"text":"“In what attitude of mind should it be diligently explained to others? Not assuming the permanency or the reality of earthly phenomena, but in the conscious blessedness of a mind at perfect rest. And why? Because, the phenomena of life may be likened unto a dream, a phantasm, a bubble, a shadow, the glistening dew, or lightning flash, and thus they ought to be contemplated.”\n\nWhen the Lord Buddha concluded his enunciation of this Scripture, the venerable Subhuti, the monks, nuns, lay-brethren and sisters, all mortals, and the whole realm of spiritual beings, rejoiced exceedingly, and consecrated to its practice, they received it and departed.","note":"The closing words of the Diamond Sutra, loved in Zen and across Mahayana Buddhism: all passing things are like a dream, a bubble, the glistening dew.","voice":"brian","source":{"name":"The Diamond Sutra (Chin-kang-ching), tr. William Gemmell (1912), p. 108 to 110","url":"https://archive.org/details/cu31924022914588"},"rights":"pd","pd":"published 1912; Gemmell died 1918"},{"id":"eastx-chuangtzu-backbone","title":"Life the Backbone, Death the Tail","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["funeral","dying","grief","peace"],"text":"Four men were conversing together, when the following resolution was suggested: “Whosoever can make Inaction the head, Life the backbone, and Death the tail, of his existence, that man shall be admitted to friendship with us.” The four looked at each other and smiled; and tacitly accepting the conditions, became friends forthwith.\n\nBy-and-by, another of the four, named Tzu Lai, fell ill, and lay gasping for breath, while his family stood weeping around. The fourth friend, Tzu Li, went to see him. “Chut!” cried he to the wife and children; “begone! you balk his decomposition.” Then, leaning against the door, he said, “Verily, God is great! I wonder what he will make of you now. I wonder whither you will be sent. Do you think he will make you into a rat's liver or into the shoulders of a snake?”\n\n“A son,” answered Tzu Lai, “must go whithersoever his parents bid him. Nature is no other than a man's parents. If she bid me die quickly, and I demur, then I am an unfilial son. She can do me no wrong. Tao gives me this form, this toil in manhood, this repose in old age, this rest in death. And surely that which is such a kind arbiter of my life is the best arbiter of my death.\n\n“Suppose that the boiling metal in a smelting-pot were to bubble up and say, ‘Make of me an Excalibur;’ I think the caster would reject that metal as uncanny. And if a sinner like myself were to say to God, ‘Make of me a man, make of me a man;’ I think he too would reject me as uncanny. The universe is the smelting-pot, and God is the caster. I shall go whithersoever I am sent, to wake unconscious of the past, as a man wakes from a dreamless sleep.”","note":"From chapter six of Chuang Tzu: four friends who welcome life and death alike, and a dying man at peace with the great smelting-pot of the universe.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 6, The Great Supreme, p. 80 to 83","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-lao-tzu-died","title":"When Lao Tzu Died","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["funeral","grief","peace"],"text":"When Lao Tzu died, Ch'in Shih went to mourn. He uttered three yells and departed.\n\nA disciple asked him saying, “Were you not our Master's friend?”\n\n“I was,” replied Ch'in Shih.\n\n“And if so, do you consider that a sufficient expression of grief at his loss?” added the disciple.\n\n“I do,” said Ch'in Shih. “I had believed him to be the man of all men, but now I know that he was not. When I went in to mourn, I found old persons weeping as if for their children, young ones wailing as if for their mothers. And for him to have gained the attachment of those people in this way, he too must have uttered words which should not have been spoken, and dropped tears which should not have been shed, thus violating eternal principles, increasing the sum of human emotion, and forgetting the source from which his own life was received. The ancients called such emotions the trammels of mortality. The Master came, because it was his time to be born; he went, because it was his time to die. For those who accept the phenomenon of birth and death in this sense, lamentation and sorrow have no place. The ancients spoke of death as of God cutting down a man suspended in the air. The fuel is consumed, but the fire may be transmitted, and we know not that it comes to an end.”","note":"From chapter three of Chuang Tzu: the Master came when it was his time and went when it was his time; the fuel is consumed, but the fire may be passed on.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 3, Nourishment of the Soul, p. 36 to 37","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-tortoise","title":"Wagging Its Tail in the Mud","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["daily","peace"],"text":"Chuang Tzu was fishing in the P'u when the prince of Ch'u sent two high officials to ask him to take charge of the administration of the Ch'u State.\n\nChuang Tzu went on fishing, and without turning his head said, “I have heard that in Ch'u there is a sacred tortoise which has been dead now some three thousand years. And that the prince keeps this tortoise carefully enclosed in a chest on the altar of his ancestral temple. Now would this tortoise rather be dead and have its remains venerated, or be alive and wagging its tail in the mud?”\n\n“It would rather be alive,” replied the two officials, “and wagging its tail in the mud.”\n\n“Begone!” cried Chuang Tzu. “I too will wag my tail in the mud.”","note":"From chapter seventeen of Chuang Tzu: a free and simple life over honors and office.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 17, Autumn Floods, p. 217","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-fishes","title":"The Pleasure of Fishes","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["nature","daily","gratitude"],"text":"Chuang Tzu and Hui Tzu had strolled on to the bridge over the Hao, when the former observed, “See how the minnows are darting about! That is the pleasure of fishes.”\n\n“You not being a fish yourself,” said Hui Tzu, “how can you possibly know in what consists the pleasure of fishes?”\n\n“And you not being I,” retorted Chuang Tzu, “how can you know that I do not know?”\n\n“If I, not being you, cannot know what you know,” urged Hui Tzu, “it follows that you, not being a fish, cannot know in what consists the pleasure of fishes.”\n\n“Let us go back,” said Chuang Tzu, “to your original question. You asked me how I knew in what consists the pleasure of fishes. Your very question shows that you knew I knew. For you asked me how I knew. I knew it from my own feelings on this bridge. “","note":"From chapter seventeen of Chuang Tzu: two friends on a bridge, and the joy we come to know through our own hearts.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 17, Autumn Floods, p. 218 to 219","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-fish-trap","title":"The Fish-Trap and the Fish","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"reflection","occasion":["daily","peace"],"text":"“The raison d’etre of a fish-trap is the fish. When the fish is caught, the trap may be ignored. The raison d’etre of a rabbit-snare is the rabbit. When the rabbit is caught the snare may be ignored. The raison d’etre of language is an idea to be expressed. When the idea is expressed, the language may be ignored. But where shall I find a man to ignore language, with whom I may be able to converse?”","note":"From chapter twenty six of Chuang Tzu, on words and the meaning beyond them.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 26, Contingencies, p. 362 to 363","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-jain-all-beings","title":"All Breathing, Living Creatures, from the Acaranga Sutra","by":"Traditional, the Acaranga Sutra","tr":"Hermann Jacobi","year":1884,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["daily","peace","nature"],"text":"The Arhats and Bhagavats of the past, present, and future, all say thus, speak thus, declare thus, explain thus: all breathing, existing, living, sentient creatures should not be slain, nor treated with violence, nor abused, nor tormented, nor driven away. This is the pure, unchangeable, eternal law, which the clever ones, who understand the world, have declared: among the zealous and the not zealous, among the faithful and the not faithful, among the not cruel and the cruel, among those who have worldly weakness and those who have not, among those who like social bonds and those who do not: ‘that is the truth, that is so, that is proclaimed in this (creed).’\n\nHaving adopted (the law), one should not hide it, nor forsake it. Correctly understanding the law, one should arrive at indifference for the impressions of the senses, and ‘not act on the motives of the world.’ ‘He who is not of this mind, how should he come to the other?’","note":"The heart of Jain ahimsa, the way of harmlessness toward every living being, from the oldest Jain scripture.","voice":"brian","source":{"name":"Gaina Sutras, part 1, tr. Hermann Jacobi, Sacred Books of the East vol. 22 (1884), Akaranga Sutra I, 4, 1, p. 36","url":"https://archive.org/details/sbe22jainasutraspart1_202002"},"rights":"pd","pd":"published 1884; Jacobi died 1937"},{"id":"eastx-jain-first-lamps","title":"The Night Mahavira Was Freed, the First Festival of Lights","by":"Bhadrabahu, the Kalpa Sutra","tr":"Hermann Jacobi","year":1884,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["funeral","season","hope","celebration"],"text":"In the fourth month of that rainy season, in the seventh fortnight, in the dark (fortnight) of Karttika, on its fifteenth day, in the last night, in the town of Papa, in king Hastipala’s office of the writers, the Venerable Ascetic Mahavira died, went off, quitted the world, cut asunder the ties of birth, old age, and death; became a Siddha, a Buddha, a Mukta, a maker of the end (to all misery), finally liberated, freed from all pains.\n\nThat night in which the Venerable Ascetic Mahavira died, &c. (all down to) freed from all pains, was lighted up by many descending and ascending gods.\n\nIn that night in which the Venerable Ascetic Mahavira died, &c. (all down to) freed from all pains, the eighteen confederate kings of Kasi and Kosala, the nine Mallakis and nine Likkhavis, on the day of new moon, instituted an illumination on the Poshadha, which was a fasting day; for they said: ‘Since the light of intelligence is gone, let us make an illumination of material matter.’","note":"From the Kalpa Sutra: on the night Mahavira reached liberation the kings lit lamps, saying, since the light of intelligence is gone, let us make a light of material things. Jains keep Diwali in his memory.","voice":"brian","source":{"name":"Gaina Sutras, part 1, tr. Hermann Jacobi, Sacred Books of the East vol. 22 (1884), Kalpa Sutra, Lives of the Ginas, p. 264 to 266","url":"https://archive.org/details/sbe22jainasutraspart1_202002"},"rights":"pd","pd":"published 1884; Jacobi died 1937"},{"id":"eastx-jain-leaf-of-the-tree","title":"The Leaf of the Tree, from the Uttaradhyayana Sutra","by":"Traditional, the Uttaradhyayana Sutra","tr":"Hermann Jacobi","year":1895,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["funeral","grief","dying","daily"],"text":"As the fallow leaf of the tree falls to the ground, when its days are gone, even so the life of men (will come to its close); Gautama, be careful all the while!\n\nAs a dew-drop dangling on the top of a blade of Kusa-grass lasts but a short time, even so the life of men; Gautama, be careful all the while!\n\nAs life is so fleet and existence so precarious, wipe off the sins you ever committed; Gautama, &c.\n\nCast aside from you all attachments, as the (leaves of) a lotus let drop off the autumnal water, exempt from every attachment, Gautama, be careful all the while!\n\nThere is now no Jina, but there is a highly esteemed guide to show the way; now being on the right path, Gautama, be careful all the while!\n\nNow you have entered on the path from which the thorns have been cleared, the great path; walk in the right path; Gautama, &c.\n\nDo not get into an uneven road like a weak burden-bearer; for you will repent of it afterwards; Gautama, &c.\n\nYou have crossed the great ocean; why do you halt so near the shore? make haste to get on the other side; Gautama, &c.\n\nGoing through the same religious practices as perfected saints, you will reach the world of perfection, Gautama, where there is safety and perfect happiness; Gautama, &c.","note":"Mahavira’s sermon to his disciple Gautama: as a leaf falls and a dew-drop fades, life is brief, so walk the path of peace with care. Read at Jain funerals and on Paryushana.","voice":"brian","source":{"name":"Gaina Sutras, part 2, tr. Hermann Jacobi, Sacred Books of the East vol. 45 (1895), Uttaradhyayana, Lecture 10, p. 41 to 45","url":"https://archive.org/details/dli.ernet.30488"},"rights":"pd","pd":"published 1895; Jacobi died 1937"},{"id":"eastx-jain-quintessence","title":"The Quintessence of Wisdom, from the Sutrakritanga","by":"Traditional, the Sutrakritanga","tr":"Hermann Jacobi","year":1895,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["daily","peace","nature"],"text":"Earth-lives are individual beings, so are water-lives, fire-lives, and wind-lives; grass, trees, corn;\n\nAnd the remaining, (viz.) the movable beings; thus are enumerated the six classes of living beings; these are all the living beings, there are no more besides.\n\nA wise man should study them with all means of philosophical research. All beings hate pains; therefore one should not kill them.\n\nThis is the quintessence of wisdom: not to kill anything. Know this to be the legitimate conclusion from the principle of the reciprocity with regard to non-killing.\n\nHe should cease to injure living beings whether they move or not, on high, below, and on earth. For this has been called the Nirvana, which consists in peace.\n\nMaster (of his senses) and avoiding wrong, he should do no harm to anybody, neither by thoughts, nor words, nor acts.","note":"From the Sutrakritanga, a Jain scripture on harmlessness: all beings love life, so we act with care in thought, word, and deed. This is peace.","voice":"brian","source":{"name":"Gaina Sutras, part 2, tr. Hermann Jacobi, Sacred Books of the East vol. 45 (1895), Sutrakritanga I, 11, p. 310 to 311","url":"https://archive.org/details/dli.ernet.30488"},"rights":"pd","pd":"published 1895; Jacobi died 1937"},{"id":"eastx-jain-life-is-dear","title":"To All Life Is Dear, from the Acaranga Sutra","by":"Traditional, the Acaranga Sutra","tr":"Hermann Jacobi","year":1884,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["daily","nature","peace"],"text":"Those who are of a steady conduct do not desire this (wealth). Knowing birth and death, one should firmly walk the path (i.e. right conduct), (and not wait for old age to commence a religious life), for there is nothing inaccessible for death. All beings are fond of life, like pleasure, hate pain, shun destruction, like life, long to live. To all life is dear.","note":"A short Jain teaching loved for its tenderness toward every creature: all beings are fond of life.","voice":"brian","source":{"name":"Gaina Sutras, part 1, tr. Hermann Jacobi, Sacred Books of the East vol. 22 (1884), Akaranga Sutra I, 2, 3, p. 19","url":"https://archive.org/details/sbe22jainasutraspart1_202002"},"rights":"pd","pd":"published 1884; Jacobi died 1937"},{"id":"eastx-bardo-clear-light","title":"Like the Void and Cloudless Sky, from the Tibetan Book of the Dead","by":"Traditional, the Bardo Thodol","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1927,"trad":["buddhist"],"denom":["tibetan","mahayana"],"type":"prayer","occasion":["dying","peace"],"text":"O nobly-born (so and so by name), the time hath now come for thee to seek the Path [in reality]. Thy breathing is about to cease. Thy guru hath set thee face to face before with the Clear Light; and now thou art about to experience it in its Reality in the Bardo state, wherein all things are like the void and cloudless sky, and the naked, spotless intellect is like unto a transparent vacuum without circumference or centre. At this moment, know thou thyself; and abide in that state. I, too, at this time, am setting thee face to face.","note":"Read softly in the ear of one who is dying in the Tibetan Buddhist tradition: the mind is open and clear like a cloudless sky.","voice":"brian","source":{"name":"The Tibetan Book of the Dead, ed. W. Y. Evans-Wentz (1927), p. 89 to 90","url":"https://archive.org/details/the-tibetan-book-of-the-dead_202401"},"rights":"pd","pd":"published 1927 (first edition, Oxford University Press); public domain in the United States since 2023"},{"id":"eastx-bardo-death-hath-come","title":"Thou Art Not the Only One, from the Tibetan Book of the Dead","by":"Traditional, the Bardo Thodol","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1927,"trad":["buddhist"],"denom":["tibetan","mahayana"],"type":"prayer","occasion":["dying","comfort","funeral"],"text":"O nobly-born, that which is called death hath now come. Thou art departing from this world, but thou art not the only one; [death] cometh to all. Do not cling, in fondness and weakness, to this life. Even though thou clingest out of weakness, thou hast not the power to remain here. Thou wilt gain nothing more than wandering in this Sangsara. Be not attached [to this world]; be not weak. Remember the Precious Trinity.\n\nO nobly-born, whatever fear and terror may come to thee in the Chinyid Bardo, forget not these words; and, bearing their meaning at heart, go forwards: in them lieth the vital secret of recognition:\n\n‘Alas! when the Uncertain Experiencing of Reality is dawning upon me here,’\n\nWith every thought of fear or terror or awe for all [apparitional appearances] set aside,\n\nMay I recognize whatever [visions] appear, as the reflections of mine own consciousness;\n\nMay I know them to be of the nature of apparitions in the Bardo:\n\nWhen at this all-important moment [of opportunity] of achieving a great end,\n\nMay I not fear the bands of Peaceful and Wrathful [Deities], mine own thought-forms.’","note":"Words read to one who has died, in the Tibetan tradition: death comes to all, so go forward with courage, knowing every vision as a reflection of your own mind.","voice":"brian","source":{"name":"The Tibetan Book of the Dead, ed. W. Y. Evans-Wentz (1927), p. 102 to 104","url":"https://archive.org/details/the-tibetan-book-of-the-dead_202401"},"rights":"pd","pd":"published 1927 (first edition, Oxford University Press); public domain in the United States since 2023"},{"id":"eastx-bardo-invocation","title":"O Ye Compassionate Ones, the Invocation for the Dying","by":"Traditional, the Bardo Thodol","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1927,"trad":["buddhist"],"denom":["tibetan","mahayana"],"type":"prayer","occasion":["dying","funeral"],"text":"O ye Buddhas and Bodhisattvas, abiding in the Ten Directions, endowed with great compassion, endowed with foreknowledge, endowed with the divine eye, endowed with love, affording protection to sentient beings, condescend through the power of your great compassion to come hither; condescend to accept these offerings actually laid out and mentally created.\n\nO ye Compassionate Ones, defend (so-and-so) who is defenceless. Protect him who is unprotected. Be his forces and his kinsmen. Protect [him] from the great gloom of the Bardo. Turn him from the red [or storm] wind of Karma, Turn him from the great awe and terror of the Lords of Death. Save him from the long narrow passage-way of the Bardo.\n\nO ye Compassionate Ones, let not the force of your compassion be weak; but aid him. Let him not go into misery [or the miserable states of existence]. Forget not your ancient vows; and let not the force of your compassion be weak.\n\nO ye Buddhas and Bodhisattvas, let not the might of the method of your compassion be weak towards this one. Catch hold of him with [the hook of] your grace. Let not the sentient being fall under the power of evil karma.\n\nO ye Trinity, protect him from the miseries of the Bardo.","note":"From the Appendix of the Tibetan Book of the Dead, said by the family and the lama, three times, as someone is dying.","voice":"brian","source":{"name":"The Tibetan Book of the Dead, ed. W. Y. Evans-Wentz (1927), p. 197 to 198","url":"https://archive.org/details/the-tibetan-book-of-the-dead_202401"},"rights":"pd","pd":"published 1927 (first edition, Oxford University Press); public domain in the United States since 2023"},{"id":"eastx-milarepa-final-good-wishes","title":"Meet in the Realm of Happiness, Milarepa’s Final Good-Wishes","by":"Milarepa","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1928,"trad":["buddhist"],"denom":["tibetan"],"type":"blessing","occasion":["funeral","blessing","peace","gratitude"],"text":"O my disciples, here assembled, hearken unto me.\nKind, indeed, have ye been unto me,\nAnd kind have I been unto you;\nMay we, thus bound together by ties of mutual helpfulness,\nMeet in the Realm of Happiness.\n\nYe donors of alms, who here are seated,\nMay ye live long, and be e’er prosperous;\nMay no perverted thought find entry to your minds;\nMay all your thoughts e’er pious be and lead to your success religiously.\n\nMay peace harmonious bless this land;\nMay it be ever free from maladies and war;\nMay there be harvests rich, and increased yield of grain;\nMay every one delight in righteousness.\n\nMay all who have beheld my face and heard my voice,\nAnd all who have my history known, and borne it in their heart,\nAnd all who have but heard my name and story,\nMeet me in the Realm of Happiness.\n\nMay those who make a study of my life\nAnd emulate it, and dedicate themselves to meditation;\nAnd each who shall transcribe, narrate, or listen to my history,\nOr whosoe’er shall read and venerate it,\nOr take it as their rule of conduct,\nMeet me in the Realm of Happiness.\n\nTo them who for devotion’s sake endure hardships,\nThere cometh boundless merit;\nTo them who shall lead others to the treading of the Path,\nBoundless gratitude is due;\nTo them who hear the story of my life,\nThere cometh boundless grace:\nBy the power of this boundless merit, gratitude, and grace,\nMay every being, as soon as they shall hear [my history], attain Deliverance,\nAnd [True] Success as soon as they shall contemplate [it].\n\nMay the places of my sojourn, and the objects whereon I have rested,\nAnd every little thing which hath been mine,\nBring peace and gladness wheresoe’er they be.\n\nThe earth, the water, fire, and air,\nAnd the ethereal spaces wheresoever they pervade,\nMay I be able to embrace them all.\n\nMay none of living creatures, none e’en of insects,\nBe bound unto sangsaric life; nay, not one of them;\nBut may I be empowered to save them all.","note":"Milarepa’s blessing on his disciples and neighbors near the end of his life, beloved in Tibetan Buddhism: may all who have known us meet in the Realm of Happiness.","voice":"brian","source":{"name":"Tibet’s Great Yogi Milarepa, ed. W. Y. Evans-Wentz (1928), p. 255 to 257","url":"https://archive.org/details/dli.ministry.06735"},"rights":"pd","pd":"published 1928; public domain in the United States since 2024"},{"id":"eastx-milarepa-earthen-pot","title":"The Earthen Pot, a Song of Milarepa","by":"Milarepa","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1928,"trad":["buddhist"],"denom":["tibetan"],"type":"poem","occasion":["grief","daily","peace"],"text":"Even the earthen pot, by having once existed, and now by existing not,\nDemonstrateth the nature of all things [component];\nBut more especially human life it symbolizeth.\nTherefore do I, Mila the Devotee,\nResolve to persevere unwaveringly.\nThe earthen pot, which constituted my sole wealth,\nBy breaking, hath now become a Guru,\nFor it preacheth unto me a wondrous sermon on Impermanence.","note":"Milarepa sang this when his only cooking pot broke in his mountain cave: even a broken pot becomes a teacher of the passing nature of all things.","voice":"brian","source":{"name":"Tibet’s Great Yogi Milarepa, ed. W. Y. Evans-Wentz (1928), p. 214","url":"https://archive.org/details/dli.ministry.06735"},"rights":"pd","pd":"published 1928; public domain in the United States since 2024"},{"id":"eastx-hasid-grass-sings","title":"Each Blade of Grass Sings a Song to God","by":"Rabbi Nahman of Bratzlav, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["nature","season","gratitude"],"text":"He perceived that all creation was yearning for God and singing in praise of His Name. “In the winter,” Rabbi Nahman used to say, “all grasses and plants are dead; at the approach of summer, they come to life again, and each blade of grass sings a song to God. How delightful it is to listen to their songs.”","note":"A teaching of Rabbi Nahman of Bratzlav, the Hasidic master who prayed in the fields and forests.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 82 to 83","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-solitude","title":"An Hour Alone in the Open Air","by":"Rabbi Nahman of Bratzlav, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["daily","nature","peace"],"text":"Solitude is given great importance in Hassidism, more especially in the Hassidism of Bratzlav. “Solitude,” Rabbi Nahman used to say, “is the highest state. Only in solitude can man attain to the abnegation of the ‘Ego,’ (Bitul hoyesh) and thus attain union with the eternal God. Therefore a man must seek to be alone, at least for an hour each day. Especially at night, when everyone is asleep and all things are quiet. Solitude in the open air, in the forest or in the desert is of the utmost importance.”","note":"Rabbi Nahman’s counsel to spend time alone each day, outdoors among trees and fields, speaking with God in one’s own words.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 95 to 96","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-one-room","title":"From One Room into the Other","by":"Rabbi Nahman of Bratzlav, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["funeral","grief","hope"],"text":"Rabbi Nahman wished that even after his death he should continue to be among his Hassidim, as he was with them during his life. He hinted to them that it would not be necessary for them to look for another leader when he died, because he would still be among them. “To the Zaddik there is no distinction between death and life,” he once said. “Previously he lived here and then he chose the other world to be his place of abode; it is as if he had gone from one room into the other, and he will certainly hear if any one calls him.”","note":"Rabbi Nahman’s words about death, which Bratzlav Hasidim still repeat: it is as if one has gone from one room into the other.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 91","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-humble-king","title":"The King Who Walked Behind His Carriage","by":"The Baal Shem Tov, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"story","occasion":["daily"],"text":"“One should always be humble. Humility should not be expressed by the bowing of the head; this is but external humility, which is unworthy; it must be internal humility, a humility which has its origin in wisdom.” Here Rabbi Nahman followed in the foot-steps of Besht, who told a parable to illustrate this point: “A certain king wished to make his humility known publicly, so he ordered his carriage to go before him, while he went on foot behind. A wise man, whom he met by the way, objected that this was not humility: ‘Get into your carriage,’ he said, ‘and lead a modest life: this is real modesty, which comes from the heart!’”","note":"A parable of the Baal Shem Tov, founder of Hasidism, on humility that comes from the heart.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 99","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-coachman","title":"The Coachman Who Prayed While Oiling the Wheels","by":"Rabbi Levi Yitzhok of Berditchev, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"story","occasion":["daily","gratitude"],"text":"“One day,” relates folklore, “Rabbi Levi Yitzhok noticed, while on his journey, that his Jewish coachman was saying his morning prayers and oiling the wheels of the coach at the same time. A great inspiration flooded his heart at the sight of this, and he cried out aloud: ‘Lord of the world, behold how much Thy people love Thee and serve Thee. Even when oiling cart-wheels they do not forget Thee. And Thou darest to complain against Israel’.”","note":"A favorite story of the Hasidic master of Berditchev, who always looked for the good in people.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 43","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-if-not-higher","title":"If Not Higher","by":"I. L. Peretz","tr":"Helena Frank","year":1906,"trad":["jewish"],"denom":["hasidic"],"type":"story","occasion":["daily","forgiveness","healing","season"],"text":"And the Rebbe of Nemirov, every Friday morning early at Sliches-time, disappeared, melted into thin air! He was not to be found anywhere, either in the synagogue or in the two houses-of-study, or worshipping in some Minyan, and most certainly not at home. His door stood open, people went in and out as they pleased, no one ever stole anything from the Rebbe, but there was not a soul in the house.\n\nWhere can the Rebbe be?\n\nWhere should he be, if not in heaven?\n\nIs it likely a Rebbe should have no affairs on hand with the Solemn Days so near?\n\nJews (no evil eye!) need a livelihood, peace, health, successful match-makings, they wish to be good and pious and their sins are great, and Satan with his thousand eyes spies out the world from one end to the other, and he sees, and accuses, and tells tales, and who shall help if not the Rebbe? So thought the people.\n\nOnce, however, there came a Lithuanian, and he laughed! You know the Lithuanian Jews, they rather despise books of devotion, but stuff themselves with the Talmud and the codes. Well, the Lithuanian points out a special bit of the Gemoreh, and hopes it is plain enough: even Moses our Teacher could not ascend into heaven, but remained suspended thirty inches below it, and who, I ask you, is going to argue with a Lithuanian?\n\nWhat becomes of the Rebbe?\n\n“I don’t know, and I don’t care,” says he, shrugging his shoulders, and all the while (what it is to be a Lithuanian!) determined to find out.\n\nThe very same evening, soon after prayers, the Lithuanian steals into the Rebbe’s room, lays himself down under the Rebbe’s bed, and lies low.\n\nHe intends to stay there all night to find out where the Rebbe goes, and what he does at Sliches-time.\n\nAnother in his place would have dozed and slept the time away. Not so a Lithuanian, he learned a whole treatise of the Talmud by heart!\n\nDay has not broken when he hears the call to prayer.\n\nThe Rebbe has been awake some time. The Lithuanian has heard him sighing and groaning for a whole hour. Whoever has heard the groaning of the Nemirover Rebbe knows what sorrow for All-Israel, what distress of mind, found voice in every groan. The soul that heard was dissolved in grief. But the heart of a Lithuanian is of cast-iron. The Lithuanian hears and lies still. The Rebbe lies still, too, the Rebbe, long life to him, upon the bed and the Lithuanian under the bed!\n\nAfter that the Lithuanian hears the beds in the house squeak, the people jump out of them, a Jewish word is spoken now and again, water is poured on the fingers, a door is opened here and there. Then the people leave the house, once more it is quiet and dark, only a very little moonlight comes in through the shutter.\n\nHe confessed afterwards, did the Lithuanian, that when he found himself alone with the Rebbe terror took hold of him. He grew cold all over, and the roots of his ear-locks pricked his temples like needles. An excellent joke, to be left alone with the Rebbe at Sliches-time before dawn!\n\nBut a Lithuanian is dogged. He quivers and quakes like a fish, but he does not budge.\n\nAt last the Rebbe, long life to him, rises in his turn.\n\nFirst he does what beseems a Jew. Then he goes to the wardrobe and takes out a packet, which proves to be the dress of a peasant: linen trousers, high boots, a pelisse, a wide felt hat, and a long and broad leather belt studded with brass nails. The Rebbe puts them on.\n\nOut of the pockets of the pelisse dangles the end of a thick cord, a peasant’s cord.\n\nOn his way out the Rebbe steps aside into the kitchen, stoops, takes a hatchet from under a bed, puts it into his belt, and leaves the house. The Lithuanian trembles, but he persists.\n\nA fearful, Solemn-Day hush broods over the dark streets, broken not unfrequently by a cry of supplication from some little Minyan, or the moan of some sick person behind a window.\n\nThe Rebbe keeps to the street side, and walks in the shadow of the houses.\n\nHe glides from one to the other, the Lithuanian after him. And the Lithuanian hears the sound of his own heart-beats mingle with the heavy footfall of the Rebbe; but he follows on, and together they emerge from the town.\n\nBehind the town stands a little wood. The Rebbe, long life to him, enters it. He walks on thirty or forty paces, and then he stops beside a small tree. And the Lithuanian, with amaze, sees the Rebbe take his hatchet and strike the tree. He sees the Rebbe strike blow after blow, he hears the tree creak and snap. And the little tree falls, and the Rebbe splits it up into logs, and the logs into splinters. Then he makes a bundle, binds it round with the cord, throws it on his shoulder, replaces the hatchet in his belt, leaves the wood, and goes back into the town.\n\nIn one of the back streets he stops beside a poor, tumble-down little house, and taps at the window.\n\n“Who is there?” cries a frightened voice within. The Lithuanian knows it to be the voice of a Jewess, a sick Jewess.\n\n“I,” answers the Rebbe in the peasant tongue.\n\n“Who is I?” inquires the voice further. And the Rebbe answers again in the Little-Russian speech:\n\n“Vassil.”\n\n“Which Vassil? and what do you want, Vassil?”\n\n“I have wood to sell,” says the sham peasant, “very cheap, for next to nothing.”\n\nAnd without further ado he goes in. The Lithuanian\n\nsteals in behind him, and sees, in the gray light of dawn, a poor room with poor, broken furniture.\n\nIn the bed lies a sick Jewess huddled up in rags, who says bitterly:\n\n“Wood to sell, and where am I, a poor widow, to get the money from to buy it?”\n\n“I will give you a six-groschen worth on credit.”\n\n“And how am I ever to repay you?” groans the poor woman.\n\n“Foolish creature!” the Rebbe upbraids her. “See here: you are a poor sick Jewess, and I am willing to trust you with the little bundle of wood; I believe that in time you will repay me. And you, you have such a great and mighty God, and you do not trust Him! not even to the amount of a miserable six-groschen for a little bundle of wood!”\n\n“And who is to light the stove?” groans the widow. “Do I look like getting up to do it? and my son away at work!”\n\n“I will also light the stove for you,” said the Rebbe.\n\nAnd the Rebbe, while he laid the wood in the stove, repeated groaning the first part of Sliches.\n\nThen, when the stove was alight, and the wood crackled cheerily, he repeated, more gaily, the second part of Sliches.\n\nHe repeated the third part when the fire had burnt itself out, and he shut the stove doors.\n\nThe Lithuanian who saw all this remained with the Rebbe, as one of his followers.\n\nAnd later, when anyone told how the Rebbe early every morning at Sliches-time raised himself and flew up into heaven, the Lithuanian, instead of laughing, added quietly:\n\n“If not higher.”","note":"The best loved Hasidic story in English: the Rebbe who vanished before dawn at the Days of Awe was found chopping wood for a sick widow. Told by Yiddish master I. L. Peretz.","voice":"brian","source":{"name":"Stories and Pictures, I. L. Peretz, tr. Helena Frank (Jewish Publication Society, 1906), p. 13 to 18","url":"https://archive.org/details/stories-and-pictures"},"rights":"pd","pd":"published 1906; Peretz died 1915"},{"id":"eastx-japanese-death-poems","title":"Five Japanese Death Poems","by":"Basho, Arakida Moritake, Seibu, Shushiki, and Yokoi Yayu","tr":"Basil Hall Chamberlain","year":1902,"trad":["buddhist","shinto","sbnr"],"denom":["zen"],"type":"poem","occasion":["funeral","dying","grief"],"text":"Ta’en ill while journeying, I dreamt\nI wandered o’er a withered moor.\nBasho\n\nAh! yes, as a convolvulus\nTo-day my lifetime will appear.\nArakida Moritake\n\nThe daylight dawns, and, like a flower,\nOpen the gates of Paradise.\nSeibu\n\nThe dream I dreamt has faded, but\nThe iris keeps its colours yet.\nShushiki\n\nIs life then short? This dream of mine\nSeems long enough that now has faded.\nYokoi Yayu","note":"Japanese poets wrote a short farewell verse as death drew near. These five, from Basho to the poetess Shushiki, are gentle and full of the passing seasons.","voice":"brian","source":{"name":"Basil Hall Chamberlain, Basho and the Japanese Poetical Epigram, Transactions of the Asiatic Society of Japan (1902)","url":"https://archive.org/details/basho-and-the-japanses-poetical-epigram"},"rights":"pd","pd":"published 1902; Chamberlain died 1935"},{"id":"eastx-chiyo-elegies","title":"Two Elegies of Chiyo","by":"Kaga no Chiyo","tr":"Basil Hall Chamberlain","year":1902,"trad":["buddhist","sbnr"],"type":"poem","occasion":["grief","funeral"],"text":"Whether I lay me down or wake,\nHow large seems the mosquito-net!\n\nWhere may he have gone off to-day,\nThe hunter after dragon-flies?","note":"The great poetess Chiyo wrote the first for her husband, who died young, and the second for her little son, who used to chase dragonflies in the sunshine.","voice":"brian","source":{"name":"Basil Hall Chamberlain, Basho and the Japanese Poetical Epigram, Transactions of the Asiatic Society of Japan (1902)","url":"https://archive.org/details/basho-and-the-japanses-poetical-epigram"},"rights":"pd","pd":"published 1902; Chamberlain died 1935","denom":[]},{"id":"eastx-barah-maha-chet","title":"In Chet, the Month of Spring, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","nature","morning"],"text":"In Chet worship God and you shall greatly rejoice.\nYou shall obtain Him by meeting saints and repeating His name.\nIt is only those who have found their God, whose advent into the world is of account:\nVain is his birth who liveth even for a moment without Him.\nGod is equally contained in sea and land, the nether regions, the firmament, and the forests.\nWith how much pain shall man reckon if God enter not his heart?\nThey who repeat God's name are very fortunate.\nNanak, my mind desireth, my mind thirsteth for a sight of God.\nI shall touch his feet who causeth me to meet God in the month of Chet.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Chet (March to April), the first month of the Sikh year and the start of spring.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 124 to 125","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-baisakh","title":"In Baisakh, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","celebration"],"text":"In Baisakh how can they find consolation who are separated from God, in whose hearts there is no love,\nWho forget Him the Friend, and attach themselves to deceitful mammon?\nSon, wife, wealth remain not; God alone perisheth not.\nThe whole world is strangled in its love of false occupations.\nAll but the name of the one God shall be lost on man's last journey.\nHe who forgetteth God is ruined; there is none but Him.\nPure is the fame of those who are attached to the feet of the Beloved.\nNanak's prayer, O God, is, ‘Unite me with Thee that I may obtain Thee.’\nBaisakh is then delightful when the saints cause man to meet God.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Baisakh (April to May), the month of Vaisakhi and the harvest.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 125","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-jeth","title":"In Jeth, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","daily"],"text":"In Jeth man should unite with God before whom all bow.\nHe who clingeth to the skirt of God, the Friend, shall never be bound by any one.\nGod's name is like gems and pearls which none may steal.\nIn God are all the loves which delight the mind.\nWhat God desireth He doeth, and creatures act according to His will.\nThey whom God hath made His own are blest.\nCould men on their own account meet God, why should they weep in separation?\nNanak, God is obtained by association with the saints; and they who obtain Him are happy.\nIn Jeth the playful God is obtained by the fortunate for whom it hath been so recorded.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Jeth (May to June), the hot season.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 125 to 126","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-sawan","title":"In Sawan, the Month of Rain, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","nature"],"text":"In Sawan happy is the woman who loveth God's lotus feet.\nHer mind and body are imbued with true love, and her one support is the Name.\nThe love of worldly pleasures is false; everything we see shall become ashes.\nPleasant are the drops of God's nectar; he shall drink them who meeteth saints.\nThe woods and glades rejoice with God the omnipotent and unequalled.\nMy mind longeth to meet God; His favour shall cause me to meet Him.\nI am ever a sacrifice to my companions who have met God.\nNanak, God mercifully regenerateth men with the Word.\nSawan is pleasant for those who clasp God's name to their hearts.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Sawan (July to August), the rainy season, when the woods and glades rejoice.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 126 to 127","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-assu","title":"In Assu, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","comfort"],"text":"In Assu ariseth the pang of love how man can meet God.\nThe mind and body greatly thirst for a sight of some one to come and cause us to meet God.\nI fall at the feet of the saints who support me in my love.\nHow can any one obtain happiness but in God? there is no place beside.\nThey who have tasted the juice of love are satiated and cloyed.\nHumbling thyself make this supplication, ‘God, attach me to Thy skirt!’\nThey whom God the Spouse united with Himself shall never be separated from Him.\nNanak, there is no other shelter than God.\nIn Assu they dwell happy to whom God showeth mercy.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Assu (September to October), a month of longing for the Beloved.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 127","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-maghar","title":"In Maghar, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","peace"],"text":"The month of Maghar is beautiful for those who sit with their beloved God.\nHow can their glory be told whom God blendeth with Himself?\nThe bodies and minds of those who have the saints for their companions rejoice in the Lord.\nThey who are deprived of the society of the saints dwell alone;\nTheir pain never departeth; they are bound in the thrall of Death.\nThey who have enjoyed their Lord are seen ever standing in His service.\nTheir necklaces are set with God for gems, jewels, and rubies.\nNanak desireth the dust of the feet of those who fall for shelter at God's door.\nThey who worship God in Maghar shall never be born again.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Maghar (November to December), a month beautiful for those who sit with God.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 128","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-poh","title":"In Poh, the Month of Cold, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","comfort","home"],"text":"In Poh cold shall never be felt by those whom the Lord God hath embraced.\nGod's lotus feet have entered my heart, and I desire to behold Him.\nTake shelter in God and His service shall be thy gain.\nOn meeting the holy sing God's praises and sin shall not affect thee.\nThou shalt be blended with what thou hast sprung from; wherefore be absorbed in true love.\nHe whom the Supreme Being hath taken by the hand shall never be separated from Him.\nI am a hundred thousand times a sacrifice to God the Friend, the unapproachable and unfathomable.\nNanak hath fallen at God's door: it is to His honour to protect him.\nPoh is agreeable and bringeth all happiness to him whom God pardoneth.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Poh (December to January), when those God has embraced stay warm through the cold.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 128 to 129","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-magh","title":"In Magh, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","daily","forgiveness"],"text":"In Magh bathe in the dust of the saints' feet;\nMeditate on God's name, and bestow it upon all;\nSo shall the filth of the sins of births be washed away, and pride vanish from thy heart.\nLust and anger shall not seduce, and the dog covetousness shall be destroyed.\nThe world praiseth those who walk in the true way.\nMercy to human beings is more acceptable than bathing at the sixty-eight places of pilgrimage, and than all alms offered there:\nHe on whom God mercifully bestoweth it is a wise man.\nNanak is a sacrifice to those who have met their Lord.\nIn Magh they to whom the perfect Guru is kind are called the pure.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Magh (January to February): mercy to every human being is better than every pilgrimage.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 129","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-phagun","title":"In Phagun, a Song of Rejoicing, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","celebration","gratitude"],"text":"In Phagun they enjoy happiness to whom God hath manifested Himself.\nThe saints who render man assistance with God have mercifully blended me with Him.\nSince then my couch is beautiful; I possess all happiness, and there is no room for sorrow.\nMy desires have been fulfilled; I am very fortunate in having obtained God as my Spouse.\nMy companions, come to me, sing a song of rejoicing, and chant the hymns of the Lord.\nNobody appeareth like God; no one is equal to Him.\nHe hath prepared for me this world and the next, and given me a stable position.\nHe hath rescued me from the ocean of the world, and I shall not again have to run through births.\nMy tongue is but one, while manifold are His attributes: Nanak is saved by falling at His feet.\nIn Phagun ever praise Him who hath not a particle of avarice.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. Phagun (February to March), the last month of the Sikh year, a month of rejoicing and Hola Mohalla.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 129 to 130","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-all-months","title":"All Months, Days, and Minutes Are Good, from the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["season","gratitude","blessing"],"text":"The affairs of those who meditated on the Name have been adjusted.\nThey who adore God the perfect Guru shall be found genuine in His court.\nGod's feet are the basis of all comforts; through them man crosseth over the terrible and dangerous ocean.\nThey who have obtained love and devotion burn not in sin.\nTheir falsehood hath vanished, their worldliness hath disappeared, and they are filled to the brim with the truth.\nThey serve God the supreme Being, and put Him alone in their hearts.\nAll months, days, and minutes are good for him on whom God looketh with favour.\nNanak craveth the boon of a sight of Thee, O God; be Thou merciful unto him.","note":"From Guru Arjan’s Barah Maha, the Twelve Months, read in Sikh gurdwaras on the first day of each month. The closing verse of the Barah Maha: every month and every minute is good when God looks with favour.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 130","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-tegh-bahadur-blend","title":"Thou Shalt Blend with That from Which Thou Hast Sprung","by":"Guru Tegh Bahadur","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["funeral","grief","dying"],"text":"God is the Saviour of sinners, the Dispeller of fear, the Lord of the helpless;\nSaith Nanak, know Him, He dwelleth ever with thee.\n\nO clever and wise man, know that thy body is composed of five elements;\nBe sure, Nanak, that thou shalt blend with that from which thou hast sprung.\n\nKnow that the world is like a dream or a play;\nThere is nothing real in it, Nanak, but God.\n\nAs bubbles are formed from water and continually disappear;\nSo was this world constructed, saith Nanak; hear this, O my friend.\n\nKnow, my friend, that the structure of the world is all unstable;\nSaith Nanak, like a wall of sand it is not permanent.\n\nWhat is born dieth to-day, to-morrow, or the next day;\nNanak, sing God's praises, and lay aside all entanglements.\n\nGod's name to which nothing is equal I have clasped to my heart;\nBy remembering it my troubles are at an end, and I behold Thee, O God!","note":"Sloks of the ninth Guru, sung at the close of the Guru Granth Sahib and at the bhog after a Sikh funeral: the body returns to the elements, and God dwells ever with us.","voice":"brian","source":{"name":"The Sikh Religion, vol. 4, tr. Max Arthur Macauliffe (1909), Sloks of Guru Teg Bahadur, p. 414 to 421","url":"https://archive.org/details/thesikhreligioni03macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-tegh-bahadur-saved","title":"Know That He Is Saved, Sloks of Guru Tegh Bahadur","by":"Guru Tegh Bahadur","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","peace","funeral"],"text":"Saith Nanak, hear, O man, in God's image is he\nWho is unaffected by weal or woe, by covetousness, worldly love, or pride.\n\nSaith Nanak, hear, O man, know that he is saved\nWho uttereth neither praise nor blame, and to whom gold and iron are the same.\n\nSaith Nanak, hear, O man, know that he is saved\nWho feeleth neither joy nor sorrow, and who treateth an enemy and a friend as the same.\n\nSaith Nanak, hear, O man, call him a person possessed of divine knowledge,\nWho inspireth no fear, and who hath no fear of others.\n\nMan shall find many companions in weal, but none in woe;\nSaith Nanak, worship God, O man, and He will assist thee at the last moment.\n\nKnow that he in whose heart there is recollection of God, hath obtained salvation;\nBetween that man and God there is no difference; Nanak, accept this as a fact.","note":"Sloks of the ninth Guru on a steady heart: one who lives fearless and gentle, who treats friend and foe the same, is in God’s image.","voice":"brian","source":{"name":"The Sikh Religion, vol. 4, tr. Max Arthur Macauliffe (1909), Sloks of Guru Teg Bahadur, p. 415 to 419","url":"https://archive.org/details/thesikhreligioni03macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-chuangtzu-useless-tree","title":"The Big Useless Tree","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["nature","peace","daily"],"text":"Hui Tzu said to Chuang Tzu, “Sir, I have a large tree, of a worthless kind. Its trunk is so irregular and knotty that it cannot be measured out for planks; while its branches are so twisted as to admit of no geometrical subdivision whatever. It stands by the roadside, but no carpenter will look at it. And your words, sir, are like that tree; big and useless, not wanted by anybody.”\n\n“Sir,” rejoined Chuang Tzu, “have you never seen a wild cat, crouching down in wait for its prey? Right and left it springs from bough to bough, high and low alike, until perchance it gets caught in a trap or dies in a snare. On the other hand, there is the yak with its great huge body. It is big enough in all conscience, but it cannot catch mice.\n\n“Now if you have a big tree and are at a loss what to do with it, why not plant it in the domain of non-existence, whither you might betake yourself to inaction by its side, to blissful repose beneath its shade?\n\nThere it would be safe from the axe and from all other injury; for being of no use to others, itself would be free from harm.”","note":"From the first chapter of Chuang Tzu: rest in the shade of the humble, unwanted tree, and live safe and free.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 1, Transcendental Bliss, p. 10 to 11","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-great-dream","title":"The Great Awakening","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"reflection","occasion":["funeral","grief","dying","hope"],"text":"“How do I know that love of life is not a delusion after all? How do I know but that he who dreads to die is not as a child who has lost the way and cannot find his home?\n\n“The lady Li Chi was the daughter of Ai Feng. When the Duke of Chin first got her, she wept until the bosom of her dress was drenched with tears. But when she came to the royal residence, and lived with the Duke, and ate rich food, she repented of having wept. How then do I know but that the dead repent of having previously clung to life?\n\n“Those who dream of the banquet, wake to lamentation and sorrow. Those who dream of lamentation and sorrow wake to join the hunt. While they dream, they do not know that they dream. Some will even interpret the very dream they are dreaming; and only when they awake do they know it was a dream. By and by comes the Great Awakening, and then we find out that this life is really a great dream. Fools think they are awake now, and flatter themselves they know if they are really princes or peasants. Confucius and you are both dreams; and I who say you are dreams, I am but a dream myself. This is a paradox. Tomorrow a sage may arise to explain it; but that tomorrow will not be until ten thousand generations have gone by.","note":"From the second chapter of Chuang Tzu: perhaps the one who fears death is like a child who has lost the way home, and by and by comes the Great Awakening.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 2, The Identity of Contraries, p. 29 to 30","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-sacred-oak","title":"The Sacred Oak","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["nature","daily","peace"],"text":"A certain artisan was travelling to the Ch'i State. On reaching Ch'ii-yuan, he saw a sacred tree, large enough to hide an ox behind it, a hundred spans in girth, towering up ten cubits over the hill top, and carrying behind it branches, many tens of the smallest of which were of a size for boats. Crowds stood gazing at it, but our artisan took no notice, and went on his way without even casting a look behind. His apprentice however gazed his fill, and when he caught up his master, said, “Ever since I have handled an adze in your service, I have never seen such a splendid piece of timber as that. How was it that you, sir, did not care to stop and look at it?”\n\n“It's not worth talking about,” replied his master. “It's good for nothing. Make a boat of it, 'twould sink. A coffin, 'twould rot. Furniture, 'twould soon break down. A door, 'twould sweat. A pillar, 'twould be worm-eaten. It is wood of no quality, and of no use. That is why it has attained its present age.”\n\nWhen the artisan reached home, he dreamt that the tree appeared to him in a dream and spoke as follows: “What is it that you compare me with? Is it with the more elegant trees? The cherry-apple, the pear, the orange, the pumelo, and other fruit-bearers, as soon as their fruit ripens are stripped and treated with indignity. The great boughs are snapped off, the small ones scattered abroad. Thus do these trees by their own value injure their own lives. They cannot fulfil their allotted span of years, but perish prematurely in mid-career from their entanglement with the world around them. Thus it is with all things. For a long period my aim was to be useless. Many times I was in danger, but at length I succeeded, and so became useful as I am to-day. But had I then been of use, I should not now be of the great use I am. Moreover, you and I belong both to the same category of things. Have done then with this criticism of others. Is a good-for-nothing fellow whose dangers are not yet passed a fit person to talk of a good-for-nothing tree?”\n\nWhen our artisan awaked and told his dream, his apprentice said, “If the tree aimed at uselessness, how was it that it became a sacred tree?”\n\n“What you don't understand,” replied his master, “don't talk about. That was merely to escape from the attacks of its enemies. Had it not become sacred, how many would have wanted to cut it down! The means of safety adopted were different from ordinary means.”","note":"From chapter four of Chuang Tzu: an old oak that seemed useless, and so lived long, speaks in a dream about the worth of every living thing.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 4, Man Among Men, p. 50 to 52","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-ratana-sutta","title":"The Jewel Discourse, from the Ratana Sutta","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["healing","blessing","peace"],"text":"Whatever spirits have come together here, either belonging to the earth or living in the air, let all spirits be happy, and then listen attentively to what is said.\n\nTherefore, O spirits, do ye all pay attention, show kindness to the human race who both day and night bring their offerings; therefore protect them strenuously.\n\nWhatever wealth there be here or in the other world, or whatever excellent jewel in the heavens, it is certainly not equal to Tathagata. This excellent jewel (is found) in Buddha, by this truth may there be salvation.\n\nThe destruction (of passion), the freedom from passion, the excellent immortality which Sakyamuni attained (being) composed, there is nothing equal to that Dhamma. This excellent jewel (is found) in the Dhamma, by this truth may there be salvation.\n\nThe purity which the best of Buddhas praised, the meditation which they call uninterrupted, there is no meditation like this. This excellent jewel (is found) in the Dhamma, by this truth may there be salvation.\n\nAs in a clump of trees with their tops in bloom in the first heat of the hot month, so (Buddha) taught the excellent Dhamma leading to Nibbana to the greatest benefit (for all). This excellent jewel (is found) in Buddha, by this truth may there be salvation.\n\nWhatever spirits have come together here, either belonging to the earth or living in the air, let us worship the perfect (tathagata) Buddha, revered by gods and men; may there be salvation.\n\nWhatever spirits have come together here, either belonging to the earth or living in the air, let us worship the perfect (tathagata) Dhamma, revered by gods and men; may there be salvation.\n\nWhatever spirits have come together here, either belonging to the earth or living in the air, let us worship the perfect (tathagata) Sangha, revered by gods and men; may there be salvation.","note":"From the Ratana Sutta, one of the protective chants (paritta) Theravada monks recite for blessing, healing, and peace in a home.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Ratanasutta, p. 37 to 40","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-pure-land-setting-sun","title":"The Meditation on the Setting Sun, from the Amitayur-dhyana Sutra","by":"Traditional, the Pure Land sutras","tr":"Junjiro Takakusu","year":1894,"trad":["buddhist"],"denom":["mahayana","pureland"],"type":"scripture","occasion":["evening","peace","nature"],"text":"Buddha then replied: ‘Thou and all other beings besides ought to make it their only aim, with concentrated thought, to get a perception of the western quarter. You will ask how that perception is to be formed. I will explain it now. All beings, if not blind from birth, are uniformly possessed of sight, and they all see the setting sun. Thou shouldst sit down properly, looking in the western direction, and prepare thy thought for a close meditation on the sun; cause thy mind to be firmly fixed (on it) so as to have an unwavering perception by the exclusive application (of thy thought), and gaze upon it (more particularly) when it is about to set and looks like a suspended drum.\n\n‘After thou hast thus seen the sun, let (that image) remain clear and fixed, whether thine eyes be shut or open; such is the perception of the sun, which is the First Meditation.’","note":"The first of the sixteen meditations the Buddha taught Queen Vaidehi in the Pure Land tradition: watch the setting sun until its image stays clear in the mind.","voice":"brian","source":{"name":"Buddhist Mahayana Texts, Sacred Books of the East vol. 49 (1894), The Amitayur-dhyana-sutra, tr. J. Takakusu, p. 169 to 170","url":"https://archive.org/details/buddhistmahy02cowe"},"rights":"pd","pd":"published 1894; public domain by date of publication"},{"id":"eastx-zor-fravashis-come-home","title":"Who Will Remember Us?, from the Farvardin Yasht","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"scripture","occasion":["grief","season","home","funeral"],"text":"We worship the good, strong, beneficent Fravashis of the faithful, who come and go through the borough at the time of the Hamaspathmaedha; they go along there for ten nights, asking thus:\n\n‘Who will praise us? Who will offer us a sacrifice? Who will meditate upon us? Who will bless us? Who will receive us with meat and clothes in his hand and with a prayer worthy of bliss? Of which of us will the name be taken for invocation? Of which of you will the soul be worshipped by you with a sacrifice? To whom will this gift of ours be given, that he may have never-failing food for ever and ever?’\n\nAnd the man who offers them up a sacrifice, with meat and clothes in his hand, with a prayer worthy of bliss, the awful Fravashis of the faithful, satisfied, unharmed, and unoffended, bless thus:\n\n‘May there be in this house flocks of animals and men! May there be a swift horse and a solid chariot! May there be a man who knows how to praise God and rule in an assembly, who will offer us sacrifices with meat and clothes in his hand, and with a prayer worthy of bliss.’","note":"From the hymn to the Fravashis, the guardian spirits of the faithful departed, who are welcomed home in the last ten days of the Zoroastrian year (Muktad) with prayers, flowers, and gifts to the poor.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Farvardin Yasht 13, 49 to 52, p. 192 to 193","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-one-soul-two-bodies","title":"One Soul in Two Bodies","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["wedding","blessing"],"text":"They are not husband and wife who sit together:\nRather are they husband and wife who have one soul and two bodies.","note":"Guru Amar Das’s words on true marriage, often quoted at an Anand Karaj, the Sikh wedding.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), Hymns of Guru Amar Das, p. 229","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-asa-wonderful","title":"Wonderful Thy Word, from Asa ki War","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["nature","gratitude","morning"],"text":"Wonderful Thy word, wonderful Thy knowledge;\nWonderful Thy creatures, wonderful their species;\nWonderful their forms, wonderful their colours;\nWonderful the animals which wander naked;\nWonderful Thy wind; wonderful Thy water;\nWonderful Thy fire which sporteth wondrously;\nWonderful the earth, wonderful the sources of production;\nWonderful the pleasures to which mortals are attached;\nWonderful is meeting, wonderful parting from Thee;\nWonderful is hunger, wonderful repletion;\nWonderful Thy praises, wonderful Thy eulogies;\nWonderful the desert, wonderful the road;\nWonderful Thy nearness, wonderful Thy remoteness;\nWonderful to behold Thee present.\nBeholding these wonderful things I remain wondering.\nNanak, they who understand them are supremely fortunate.","note":"Sung each morning in the gurdwara as part of Asa ki War, the Ballad of Hope. Guru Nanak marvels at wind, water, fire, earth, meeting and parting, every part of creation.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Asa ki War, p. 221","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-asa-true-thy-regions","title":"True Are Thy Regions, from Asa ki War","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["morning","gratitude","daily"],"text":"True are Thy regions and true Thy universes;\nTrue Thy worlds and true Thy creation;\nTrue Thine acts and all Thy thoughts;\nTrue Thine order and true Thy court;\nTrue Thy command and true Thy behest;\nTrue Thy favour and true Thy signs.\nHundreds of thousands and millions declare Thee true;\nTrue is all Thy power, true all Thy strength;\nTrue Thy praises, true Thy eulogies;\nTrue Thy might, O true King.\nNanak, true are they who meditate on the True One.","note":"Sung each morning in the gurdwara as part of Asa ki War, the Ballad of Hope. A litany of praise: all of God’s worlds, works, and gifts are true.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Asa ki War, p. 219","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-asa-great-glory","title":"Great Is His Glory, from Asa ki War","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["gratitude","celebration","morning"],"text":"Great is His glory whose name is great;\nGreat is His glory whose justice is true;\nGreat is His glory whose seat is immovable;\nGreat is His glory who understandeth our utterances;\nGreat is His greatness who knoweth all our feelings;\nGreat is His glory who giveth without consulting others;\nGreat is His glory who is all in all Himself.\nNanak, His acts cannot be described.\nAll that He did and hath to do dependeth on His own will.","note":"Sung each morning in the gurdwara as part of Asa ki War, the Ballad of Hope. Guru Nanak on the greatness of the One who gives freely and knows every heart.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Asa ki War, p. 220","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-asa-hundred-moons","title":"Were a Hundred Moons to Rise, from Asa ki War","by":"Guru Nanak and Guru Angad","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["daily","morning"],"text":"I am a sacrifice to my Guru a hundred times a day.\nWho without any delay made demigods out of men.\n\nWere a hundred moons to rise, and a thousand suns to mount the sky;\nEven with such light there would be appalling darkness without the Guru.","note":"Sung each morning in the gurdwara as part of Asa ki War, the Ballad of Hope. Two short verses on the Guru as a light brighter than a thousand suns.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Asa ki War, p. 218","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-hearn-butterflies","title":"Butterfly Poems","by":"Traditional Japanese poets","tr":"Lafcadio Hearn","year":1915,"trad":["shinto","buddhist","sbnr","nature"],"type":"poem","occasion":["nature","season","celebration"],"text":"Like a woman slipping off her haori, that is the appearance of a butterfly.\nAh, the butterfly keeps getting in the way of the bird-catcher’s pole!\nPerched upon the temple-bell, the butterfly sleeps:\nEven while sleeping, its dream is of play, ah, the butterfly of the grass!\nWake up! wake up! I will make thee my comrade, thou sleeping butterfly.\nAh, the sad expression in the eyes of that caged bird! envying the butterfly!\nEven though it did not appear to be a windy day, the fluttering of the butterflies!\n\nWhen I saw the fallen flower return to the branch, lo! it was only a butterfly!\nHow the butterfly strives to compete in lightness with the falling flowers!\nSee that butterfly on the woman's path, now fluttering behind her, now before!\nHa! the butterfly! it is following the person who stole the flowers!\nPoor autumn butterfly! when left without a comrade, it follows after man!\nAh, the butterfly! Even when chased, it never has the air of being in a hurry.\nAs for butterflies, they all have the appearance of being about seventeen or eighteen years old.\n\nHow the butterfly sports, just as if there were no enmity in this world!\nAh, the butterfly! It sports about as if it had nothing more to desire in this present state of existence.\nHaving found it difficult indeed to perch upon the (foam-) blossoms of the waves, alas for the butterfly!\nIf (in our next existence) we be reborn as butterflies upon the moor, then perchance we may be happy together!\nOn the pink-flower there is a white butterfly: whose spirit, I wonder?\nThe one-day wife has at last appeared, a pair of butterflies!\nApproaching they dance; but when the two meet at last they are very quiet, the butterflies!","note":"Short Japanese poems about butterflies, gathered by Lafcadio Hearn: light, playful, and full of the seasons.","voice":"brian","source":{"name":"Japanese Lyrics, tr. Lafcadio Hearn (1915), Insect Poems, p. 3 to 7","url":"https://archive.org/details/japaneselyrics00hearuoft"},"rights":"pd","pd":"published 1915; Hearn died 1904","denom":[]},{"id":"eastx-tu-thakur","title":"Thou Art the Lord, to Thee I Pray, from the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"prayer","occasion":["daily","comfort","healing","blessing"],"text":"Thou art the Lord: I make this supplication unto Thee.\nSoul and body are all Thy property;\nThou art mother and father, we are Thy children.\nBy Thy favour we obtain many comforts:\nNobody knoweth Thy limit.\nGod, Thou art the most exalted of the exalted.\nAll things are strung on Thy string,\nAnd must obey the orders Thou issuest.\nIt is only Thou Thyself who knowest Thine own condition and limit:\nNanak, Thy slave, is ever a sacrifice unto Thee.","note":"The eighth verse of the fourth ashtapadi of the Sukhmani, said by Sikhs as the Ardas begins and whenever the Guru Granth Sahib is opened: Thou art mother and father, we are Thy children.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, Ashtapadi 4, p. 210","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-thou-art-my-father","title":"Thou Art My Father and Mother","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["comfort","daily","forgiveness"],"text":"Relying on Thee, O Beloved, I have been made happy.\nEven if I have gone astray, I am Thy child, O God;\nThou art my father and mother.\nIt is easy to talk,\nBut to act as Thou pleasest is difficult.\nIn Thee I repose mine honour and my strength; I know Thee as mine.\nThou art within and without everything; Thou needest nothing, O Father.\nFather, I know not Thy ways.\nGod freeth me from entanglements, O saints, and cherisheth love for me.\nThe Lord hath been merciful, and my transmigration is at an end.\nOn meeting the Guru, Nanak hath recognized the Supreme God.","note":"A hymn of Guru Arjan, who speaks to God as a child to a loving parent: even if I have gone astray, I am Thy child.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Hymns of Guru Arjan, p. 107","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sala-trees","title":"The Twin Sala Trees in Bloom, from the Book of the Great Decease","by":"Traditional, the Maha-parinibbana Sutta","tr":"T. W. Rhys Davids","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["funeral","dying","nature"],"text":"Now at that time the twin Sala trees were all one mass of bloom with flowers out of season; and all over the body of the Tathagata these dropped and sprinkled and scattered themselves, out of reverence for the successor of the Buddhas of old. And heavenly Mandarava flowers, too, and heavenly sandal-wood powder came falling from the sky, and all over the body of the Tathagata they descended and sprinkled and scattered themselves, out of reverence for the successor of the Buddhas of old. And heavenly music was sounded in the sky, out of reverence for the successor of the Buddhas of old. And heavenly songs came wafted from the skies, out of reverence for the successor of the Buddhas of old!\n\nThen the Blessed One addressed the venerable Ananda, and said: ‘The twin Sala trees are all one mass of bloom with flowers out of season; all over the body of the Tathagata these drop and sprinkle and scatter themselves, out of reverence for the successor of the Buddhas of old. And heavenly Mandarava flowers, too, and heavenly sandal-wood powder come falling from the sky, and all over the body of the Tathagata they descend and sprinkle and scatter themselves, out of reverence for the successor of the Buddhas of old. And heavenly music sounds in the sky, out of reverence for the successor of the Buddhas of old. And heavenly songs come wafted from the skies, out of reverence for the successor of the Buddhas of old!’\n\n‘Now it is not thus, Ananda, that the Tathagata is rightly honoured, reverenced, venerated, held sacred or revered. But the brother or the sister, the devout man or the devout woman, who continually fulfils all the greater and the lesser duties, who is correct in life, walking according to the precepts, it is he who rightly honours, reverences, venerates, holds sacred, and reveres the Tathagata with the worthiest homage. Therefore, O Ananda, be ye constant in the fulfilment of the greater and of the lesser duties, and be ye correct in life, walking according to the precepts; and thus, Ananda, should it be taught.’","note":"From the account of the Buddha’s passing: the sala trees bloomed out of season and flowers fell like rain, yet the Buddha taught that the truest honor is a life lived well.","voice":"brian","source":{"name":"Buddhist Suttas, tr. T. W. Rhys Davids, Sacred Books of the East vol. 11 (1881), Maha-parinibbana Sutta, chapter 5, p. 86 to 87","url":"https://archive.org/details/wg911"},"rights":"pd","pd":"published 1881; Rhys Davids died 1922"},{"id":"eastx-ananda-do-not-weep","title":"Enough, Ananda, Do Not Weep, from the Book of the Great Decease","by":"Traditional, the Maha-parinibbana Sutta","tr":"T. W. Rhys Davids","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["grief","funeral","comfort","dying"],"text":"Now the venerable Ananda went into the Vihara, and stood leaning against the lintel of the door, and weeping at the thought: “Alas! I remain still but a learner, one who has yet to work out his own perfection. And the Master is about to pass away from me, he who is so kind!”\n\nThen the Blessed One said to the venerable Ananda, as he sat there by his side: ‘Enough, Ananda! Do not let yourself be troubled; do not weep! Have I not already, on former occasions, told you that it is in the very nature of all things most near and dear unto us that we must divide ourselves from them, leave them, sever ourselves from them? How, then, Ananda, can this be possible, whereas anything whatever born, brought into being, and organised, contains within itself the inherent necessity of dissolution, how, then, can this be possible, that such a being should not be dissolved? No such condition can exist! For a long time, Ananda, have you been very near to me by acts of love, kind and good, that never varies, and is beyond all measure. For a long time, Ananda, have you been very near to me by words of love, kind and good, that never varies, and is beyond all measure. For a long time, Ananda, have you been very near to me by thoughts of love, kind and good, that never varies, and is beyond all measure. You have done well, Ananda! Be earnest in effort, and you too shall soon be free from the great evils, from sensuality, from individuality, from delusion, and from ignorance!’","note":"As the Buddha neared his death, his faithful friend Ananda wept; the Buddha comforted him with thanks for a lifetime of love in deed, word, and thought.","voice":"brian","source":{"name":"Buddhist Suttas, tr. T. W. Rhys Davids, Sacred Books of the East vol. 11 (1881), Maha-parinibbana Sutta, chapter 5, p. 95 to 97","url":"https://archive.org/details/wg911"},"rights":"pd","pd":"published 1881; Rhys Davids died 1922"},{"id":"eastx-four-boundless-states","title":"Love Far-Reaching and Beyond Measure, from the Tevigga Sutta","by":"Traditional, the Tevigga Sutta","tr":"T. W. Rhys Davids","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["peace","daily","blessing","healing"],"text":"‘And he lets his mind pervade one quarter of the world with thoughts of Love, and so the second, and so the third, and so the fourth. And thus the whole wide world, above, below, around, and everywhere, does he continue to pervade with heart of Love, far-reaching, grown great, and beyond measure.\n\n‘Just, Vasettha, as a mighty trumpeter makes himself heard, and that without difficulty, in all the four directions; even so of all things that have shape or life, there is not one that he passes by or leaves aside, but regards them all with mind set free, and deep-felt love.\n\n‘Verily this, Vasettha, is the way to a state of union with Brahma.\n\n‘And he lets his mind pervade one quarter of the world with thoughts of pity, sympathy, and equanimity, and so the second, and so the third, and so the fourth. And thus the whole wide world, above, below, around, and everywhere, does he continue to pervade with heart of pity, sympathy, and equanimity, far-reaching, grown great, and beyond measure.\n\n‘Just, Vasettha, as a mighty trumpeter makes himself heard, and that without difficulty, in all the four directions; even so of all things that have shape or life, there is not one that he passes by or leaves aside, but regards them all with mind set free, and deep-felt pity, sympathy, and equanimity.\n\n‘Verily this, Vasettha, is the way to a state of union with Brahma.’","note":"The Buddha’s teaching on the boundless states of love, compassion, sympathy, and equanimity, sent out to every quarter of the world.","voice":"brian","source":{"name":"Buddhist Suttas, tr. T. W. Rhys Davids, Sacred Books of the East vol. 11 (1881), Tevigga Sutta, chapter 3, p. 201 to 202","url":"https://archive.org/details/wg911"},"rights":"pd","pd":"published 1881; Rhys Davids died 1922"},{"id":"eastx-zor-earth-most-happy","title":"Where the Earth Feels Most Happy, from the Vendidad","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1880,"trad":["zoroastrian"],"type":"scripture","occasion":["nature","home","season","gratitude"],"text":"O Maker of the material world, thou Holy One! Which is the first place where the Earth feels most happy?\n\nAhura Mazda answered: ‘It is the place whereon one of the faithful steps forward, O Spitama Zarathustra! with the holy wood in his hand, the baresma in his hand, the holy meat in his hand, the holy mortar in his hand, fulfilling the law with love, and beseeching aloud Mithra, the lord of wide pastures, and Rama Hvastra.’\n\nO Maker of the material world, thou Holy One! Which is the second place where the Earth feels most happy?\n\nAhura Mazda answered: ‘It is the place whereon one of the faithful erects a house with a priest within, with cattle, with a wife, with children, and good herds within; and wherein afterwards the cattle go on thriving, holiness is thriving, fodder is thriving, the dog is thriving, the wife is thriving, the child is thriving, the fire is thriving, and every blessing of life is thriving.’\n\nO Maker of the material world, thou Holy One! Which is the third place where the Earth feels most happy?\n\nAhura Mazda answered: ‘It is the place where one of the faithful cultivates most corn, grass, and fruit, O Spitama Zarathustra! where he waters ground that is dry, or dries ground that is too wet.’\n\n‘He who would till the earth, O Spitama Zarathustra! with the left arm and the right, with the right arm and the left, unto him will she bring forth plenty, like a loving bride on her bed, unto her beloved; the bride will bring forth children, the earth will bring forth plenty of fruit.\n\n‘He who would till the earth, O Spitama Zarathustra! with the left arm and the right, with the right arm and the left, unto him thus says the Earth: “O thou man! who dost till me with the left arm and the right, with the right arm and the left [hither shall people ever come and beg (for bread)], here shall I ever go on bearing, bringing forth all manner of food, bringing forth profusion of corn.”\n\nO Maker of the material world, thou Holy One! What is the food that fills the law of Mazda?\n\nAhura Mazda answered: ‘It is sowing corn again and again, O Spitama Zarathustra!\n\n‘He who sows corn, sows holiness: he makes the law of Mazda grow higher and higher: he makes the law of Mazda as fat as he can with a hundred acts of adoration, a thousand oblations, ten thousand sacrifices.","note":"From the third chapter of the Vendidad: the Earth is happiest where a family keeps a home, where the ground is tended, and where grain is sown. He who sows corn sows holiness.","voice":"brian","source":{"name":"The Zend-Avesta, part 1, tr. James Darmesteter, Sacred Books of the East vol. 4 (1880), Vendidad, Fargard 3, p. 22 to 30","url":"https://archive.org/details/wg904"},"rights":"pd","pd":"published 1880; Darmesteter died 1894","denom":[]},{"id":"eastx-jain-birth-of-mahavira","title":"The Birth of Mahavira, from the Kalpa Sutra","by":"Bhadrabahu, the Kalpa Sutra","tr":"Hermann Jacobi","year":1884,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["birth","celebration","blessing"],"text":"In that period, in that age the Venerable Ascetic Mahavira, after the lapse of nine months and seven and a half days, in the first month of summer, in the second fortnight, the dark (fortnight) of Kaitra, on its fourteenth day, [while all planets were in their exaltations, the moon in her principal conjunction, and the sky in all its directions clear, bright, and pure; while a favourable and agreeable low wind swept the earth; at the time when the fields were green and all people glad and amusing themselves] in the middle of the night while the moon was in conjunction with the asterism Uttaraphalguni, (Trisala), perfectly healthy herself, gave birth to a perfectly healthy boy.\n\nIn that night in which the Venerable Ascetic Mahavira was born, there was a divine lustre originated by many descending and ascending gods and goddesses, and in the universe, resplendent with one light, the conflux of gods occasioned great confusion and noise.\n\nAfter dinner they went (to the meeting hall) after having cleansed their mouths and washed; when perfectly clean, they regaled and honoured their friends . . . Gnatrika Kshatriyas with many flowers, clothes, perfumes, garlands, and ornaments. Then they spoke thus to their friends, &c.:\n\n‘Formerly, O beloved of the gods, when we had begotten this our boy, the following personal, reflectional, desirable idea occurred to our mind: “From the moment that this our boy has been begotten, our silver increased, our gold increased . . . Now our wishes have been fulfilled, therefore shall the name of our boy be Vardhamana.”’","note":"From the Kalpa Sutra, read aloud by Jains during Paryushana: the joyful birth of Mahavira, when fields were green and all people glad, and the naming feast where he was called Vardhamana, the Increasing One.","voice":"brian","source":{"name":"Gaina Sutras, part 1, tr. Hermann Jacobi, Sacred Books of the East vol. 22 (1884), Kalpa Sutra, Lives of the Ginas, p. 250 to 255","url":"https://archive.org/details/sbe22jainasutraspart1_202002"},"rights":"pd","pd":"published 1884; Jacobi died 1937"},{"id":"eastx-basho-haiku","title":"Haiku of Basho","by":"Matsuo Basho","tr":"Basil Hall Chamberlain","year":1902,"trad":["buddhist","sbnr","nature"],"denom":["zen"],"type":"poem","occasion":["nature","season","peace"],"text":"The year has closed while still I wear\nMy sandals and my pilgrim’s hat.\n\nComing this mountain way, no herb\nIs lovelier than the violet.\n\nOn looking carefully, behold\nThe caseweed flowering near the fence!\n\nWell then, we’ll off to see the snow,\nFar as we can without a tumble.\n\nAwake! awake! I’ll make of thee\nMy comrade, sleeping butterfly.\n\nNothing in the cicada’s voice\nGives token of a speedy death.\n\nA rough sea, and the Milky Way\nStretching across to Sado’s isle.\n\nThe household at the graves assembled,\nWhite-haired, and leaning on their staves.\n\nThe old pond, aye! and the sound of a frog leaping into the water.","note":"Nine short poems by Basho, the wandering poet of the seventeenth century, from his pilgrim’s hat at the year’s end to the family gathered at the graves for the summer festival of the dead.","voice":"brian","source":{"name":"Basil Hall Chamberlain, Basho and the Japanese Poetical Epigram, Transactions of the Asiatic Society of Japan (1902)","url":"https://archive.org/details/basho-and-the-japanses-poetical-epigram"},"rights":"pd","pd":"published 1902; Chamberlain died 1935"},{"id":"eastx-basho-moon-birds","title":"Moon and Birdsong, Four Haiku of Basho","by":"Matsuo Basho","tr":"Basil Hall Chamberlain","year":1902,"trad":["buddhist","sbnr","nature"],"denom":["zen"],"type":"poem","occasion":["nature","evening","peace"],"text":"Oh! skylark for whose carolling\nThe livelong day sufficeth not!\n\nAthwart the surface of the stream\nThere lieth stretched the cuckoo’s voice.\n\nIn the bright moonlight what appeared\nLike flowers is a cotton field.\n\nAs, lacking oil, I lie abed\nAt night, the moon my window lights.","note":"Four more of Basho’s short poems of the skylark, the cuckoo, and the moon that lights his window when the lamp oil is gone.","voice":"brian","source":{"name":"Basil Hall Chamberlain, Basho and the Japanese Poetical Epigram, Transactions of the Asiatic Society of Japan (1902)","url":"https://archive.org/details/basho-and-the-japanses-poetical-epigram"},"rights":"pd","pd":"published 1902; Chamberlain died 1935"},{"id":"eastx-chuangtzu-mirror","title":"Still Water Is Like a Mirror","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"reflection","occasion":["peace","daily","nature"],"text":"The repose of the Sage is not what the world calls repose. His repose is the result of his mental attitude. All creation could not disturb his equilibrium: hence his repose.\n\nWhen water is still, it is like a mirror, reflecting the beard and the eyebrows. It gives the accuracy of the water-level, and the philosopher makes it his model. And if water thus derives lucidity from stillness, how much more the faculties of the mind? The mind of the Sage being in repose becomes the mirror of the universe, the speculum of all creation. Repose, tranquillity, stillness, inaction, these were the levels of the universe, the ultimate perfection of Tao.","note":"From chapter thirteen of Chuang Tzu: as still water reflects clearly, a quiet mind becomes the mirror of the universe.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 13, The Tao of God, p. 157 to 158","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-chuangtzu-hun-tun","title":"Hun Tun and the Seven Holes","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["daily","nature"],"text":"The ruler of the southern sea was called Shu. The ruler of the northern sea was called Hu. The ruler of the central zone was called Hun Tun.\n\nShu and Hu often met on Hun Tun's territory, and being always well treated by him, determined to repay his kindness.\n\nThey said, “All men have seven holes, for seeing, hearing, eating, and breathing. Hun Tun alone has none. We will bore some for him.”\n\nSo every day they bored one hole; but on the seventh day Hun Tun died.","note":"A short parable from the end of chapter seven of Chuang Tzu, on the gentle wisdom of leaving things in their natural state.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 7, How to Govern, p. 98","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-japji-realms","title":"The Realms of Knowledge, Grace, and Truth, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["funeral","hope","daily"],"text":"Such is the practice in the realm of righteousness.\nI now describe the condition of the realm of knowledge.\nHow many winds, waters, and fires! how many Krishans and Shivs!\nHow many Brahmas who fashioned worlds! how many forms, colours, and garbs!\nHow many lands of grace like this! how many mountains! how many Dhrus and instructors such as his.\nHow many Indars, how many moons and suns, how many regions and countries!\nHow many Sidhs, Budhs, how many Naths! how many goddesses and representations of them!\nHow many demigods and demons! how many saints, how many jewels and seas!\nHow many sources of life! how many languages! and how many lines of kings!\nHow many possessors of divine knowledge! how many worshippers! Nanak, there is no end of them.\n\nIn the realm of knowledge the light of divine knowledge is resplendent.\nThere are heard songs from which millions of joys and pleasures proceed.\nBeauty is the attribute of the realm of happiness.\nThere things are fashioned in an incomparable manner.\nWhat is done there cannot be described.\nWhoever endeavoureth to describe it shall afterwards repent.\nThere are fashioned knowledge, wisdom, intellect, and understanding;\nAnd there too is fashioned the skill of demigods and men of supernatural power.\n\nForce is the attribute of the realm of action.\nIncomparable are they who dwell therein.\nThere are very powerful warriors and heroes;\nThey are filled with the might of Ram.\nThere are many Sitas in the midst of greatness,\nTheir beauty cannot be described;\nThey die not, neither are they led astray\nIn whose hearts God dwelleth.\nThere dwell congregations of saints;\nThey rejoice; the True One is in their hearts.\nGod dwelleth in the true realm.\nHe looketh on its denizens with an eye of favour, and rendereth them happy.\nThere are continents, worlds, and universes.\nWhoever trieth to describe them shall never arrive at an end.\nThere are worlds upon worlds and forms upon forms.\nThey fulfil their functions according to God’s orders:\nGod beholding and contemplating them is pleased.\nNanak, to describe them would be impossible.","note":"Pauris thirty four to thirty seven of the Japji: the soul’s journey through the realms of duty, knowledge, effort, grace, and at last the Realm of Truth, where God dwells.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 215 to 217","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-hearn-tanabata","title":"The Weaver and the Herdsman, the Legend of the River of Heaven","by":"Lafcadio Hearn","year":1915,"trad":["shinto","buddhist","sbnr"],"type":"story","occasion":["wedding","season","hope"],"text":"The great god of the firmament had a lovely daughter, Tanabata-tsume, who passed her days in weaving garments for her august parent. She rejoiced in her work, and thought that there was no greater pleasure than the pleasure of weaving. But one day, as she sat before her loom at the door of her heavenly dwelling, she saw a handsome peasant lad pass by, leading an ox, and she fell in love with him. Her august father, divining her secret wish, gave her the youth for a husband. But the wedded lovers became too fond of each other, and neglected their duty to the god of the firmament; the sound of the shuttle was no longer heard, and the ox wandered, unheeded, over the plains of heaven. Therefore the great god was displeased, and he separated the pair. They were sentenced to live thereafter apart, with the Celestial River between them; but it was permitted them to see each other once a year, on the seventh night of the seventh moon. On that night, providing the skies be clear, the birds of heaven make, with their bodies and wings, a bridge over the stream; and by means of that bridge the lovers can meet. But if there be rain, the River of Heaven rises, and becomes so wide that the bridge cannot be formed. So the husband and wife cannot always meet, even on the seventh night of the seventh month; it may happen, by reason of bad weather, that they cannot meet for three or four years at a time. But their love remains immortally young and eternally patient; and they continue to fulfil their respective duties each day without fault, happy in their hope of being able to meet on the seventh night of the next seventh month.","note":"The old East Asian star legend behind the summer festival of Tanabata: two lovers parted by the Milky Way meet once a year, their love immortally young and eternally patient.","voice":"brian","source":{"name":"Japanese Lyrics, tr. Lafcadio Hearn (1915), The River of Heaven, p. 55 to 57","url":"https://archive.org/details/japaneselyrics00hearuoft"},"rights":"pd","pd":"published 1915; Hearn died 1904","denom":[]},{"id":"eastx-hasid-joyful-with-god","title":"Be Joyful with God","by":"The Baal Shem Tov, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["daily","comfort","forgiveness","nature"],"text":"“God desires to be served in every way, we must eat and drink, speak and walk and be joyful with God. The chief things are right intentions and pure thoughts; if the thoughts of a man be pure and his intentions right then in every place where he stays, the Shechina will be with him. He needs no fixed places to say his prayers, no synagogues; among the trees in the forest, everywhere one can pray and the prayer will be heard.”\n\nFrom all that we hear and read about Besht, we must imagine him a strong, healthy man, kindhearted, always cheerful, going about a great deal, delighting to talk, and seeing the spiritual in everything; loving the field and the forest, and the open sky. And when he sometimes sees groups of Jewish people with bowed heads, bent backs, and sorrowful faces, he asks them: “Why are you so sad, why are your faces so miserable?” “We have not prayed properly” they say. “We have not studied in the right way. What are we indeed and what is our life? We have not yet accomplished even a fraction of our duties to our Creator, praised be His name!” “Cease!” cries Besht in his kindly voice, “Sorrow is a kind of Evil. If you have not studied enough, study is not the principal thing. If you have not prayed rightly, believe! A Jew works all day long in the market place; towards evening, at dusk, he trembles and says to himself: ‘Woe unto me! I almost forgot to say the evening prayer’; and he rushes into a house and says his prayer, without knowing what his lips are saying, and yet all the angels tremble at his prayer. No, the chief thing is the intention, the purity of heart and of thought. Now therefore leave sorrow and sadness; man must live in joy and gladness, rejoicing always in his lot.”","note":"Teachings of the Baal Shem Tov, founder of Hasidism, who loved the field, the forest, and the open sky, and taught that God is served with joy.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 9 to 11","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-scholar-workman","title":"The Scholar and the Workman","by":"The Baal Shem Tov, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"story","occasion":["daily","forgiveness"],"text":"There is a story which Baal-Shem once told to his disciples: In the same house there once lived a Talmud-scholar and a simple Jewish workman. Both arose very early every morning. The scholar went to the prayer-house and the workman to his toil. The scholar sat in the prayer-house for hours studying the Holy Books and praying till the dinner hour. And then well satisfied with the fulfilment of his duties to God; he returned home. On his way he met his neighbour returning tired and exhausted from his work; the workman had only a few minutes in which he could go into the prayer-house and say his morning prayer. The Talmud-scholar looked at him with contempt, and thought of the great difference between them he studying so hard and so long in the Holy Books, and praying so diligently and this simple man had been busy all the morning with coarse work, and had only just said his morning prayer. The workman sighed, fearing for himself when he looked upon his neighbour the Talmud-scholar who had left the house early in the morning, at the same time as he, and had all these hours been occupied only with holy things, whilst he had been at his hard work.\n\nWeeks, months and years passed in this way. The Talmud scholar died and not long after, the workman died too. The scholar was called before the heavenly Judge: “What hast thou done during thy life?” he was asked. “I spent my life in the study of the Talmud and in prayer” he replied, “I observed all the laws to the smallest detail”. And he stood back well satisfied. “He despised his neighbour, the workman, who had no time to pray and did not have the knowledge of the Talmud”, intervened the celestial counsel. The scales were brought out; all the Talmud studies and the prayers were placed on one side, and on the other his contempt for the workman. And behold! the contempt weighed down the scale on its side and a heavenly voice said: “The Talmud scholar has no place in Paradise.”\n\nThen the workman came up. “What hast thou done during thy life?” he was asked. And he answered with bowed head: “All my life has been spent in hard work. I had to earn my bread by the sweat of my brow to provide for my wife and children, and therefore I had no time to say my prayers properly”. “But he always looked enviously towards his neighbour, the Talmud scholar, sighing and full of humility”, intervened the celestial counsel. And behold! a divine voice cried aloud: “Bring the workman into Paradise”.","note":"A parable the Baal Shem Tov told his disciples: in heaven, a humble heart weighs more than a proud one’s learning.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 11 to 12","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-three-loves","title":"Love of God, Love of the People, Love of Torah","by":"The Baal Shem Tov, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["daily","blessing"],"text":"Once Besht was asked, “What is the essence of service? Our parents used to tell us that in ancient times pious men did penance. You have abolished this thing, saying: every one who fasts, will some day have to give an account for it to God. For the man who does penance for his soul, will be called a sinner. Why now explain to us, what is the essence of service?”. And Besht answered them: “I have come into this world to show a way, that man shall make the observance of three rules his aim in life, namely: Love of God, love of Israel and love of Torah, and with these penance is unnecessary”.\n\nA man whose rules of life consisted of love of God, love of the people and love of Torah surely was a good teacher of his people.\n\nAnd indeed Besht was a teacher unto his people. He gave them a God of love and mercy, freed them from fasting and penance, weeping and lamentations, sorrow and distress.","note":"The Baal Shem Tov’s answer when asked the essence of serving God: love of God, love of the people, and love of Torah.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 12","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-sukhmani-sloks","title":"The True One Was in the Beginning, Sloks of the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","peace","funeral","morning"],"text":"Nanak, he is an Aparas and saveth all,\nWho preserveth the Name in his inmost heart,\nWho seeth God in all things,\nAnd who every moment boweth to the Lord.\n\nThe Cause of causes is the One God, there is none other.\nNanak is a sacrifice to Him who is contained in sea and land, in the nether regions and the firmament.\n\nQuit devices, my good friends, and remember God, God the King;\nTreasure in thy heart thy hopes in the one God, O Nanak, so shall suffering, error, and fear depart.\n\nGod hath no form, outline, or colour; He is exempt from the three qualities;\nHe causeth him, O Nanak, with whom He is well pleased to know Him.\n\nThe True One was in the beginning; the True One was in the primal age.\nThe True One is now also, O Nanak; the True One also shall be.\n\nAfter many wanderings, O God, I have come to Thine asylum;\nNanak's prayer, O God, is, ‘Let me apply myself to Thy service.’\n\nLord of men and lower animals, Thou art contained in everything;\nNanak, the one God is everywhere extended; where is there another seen?\n\nThe Guru hath given the eye-salve of divine knowledge by which the darkness of ignorance is dispelled;\nThe mind of him, O Nanak, who by God's favour meeteth the saints is enlightened.\n\nHe who worshippeth the perfect God whose name is perfect,\nAnd who singeth the praises of the perfect One, O Nanak, obtaineth the perfect One.","note":"Short verses (sloks) that open the ashtapadis of the Sukhmani, Guru Arjan’s Psalm of Peace.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 224 to 269","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-zor-afrin-zarathustra","title":"I Bless Thee with a Good Life, the Blessing of Zarathustra","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"blessing","occasion":["blessing","wedding","birth","celebration"],"text":"‘I am a pious man, who speaks words of blessing.’\n\n‘Thou appearest unto me full of Glory.’\n\nAnd Zarathustra spake unto king Vishtaspa, saying: ‘I bless thee, O man! O lord of the country! with the living of a good life, of an exalted life, of a long life. May thy men live long! May thy women live long! May sons be born unto thee of thy own body!\n\n‘Mayest thou be most beneficent, like Mazda!\n\n‘Mayest thou be holy, like Zarathustra Spitama!\n\n‘Mayest thou be beloved by the gods and reverenced by men!’","note":"From the Afrin Paighambar Zartusht, the blessing Zarathustra gave King Vishtaspa, still used by Zoroastrian priests to bless families, weddings, and new beginnings.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Yasht 23, Afrin Paighambar Zartust, p. 325 to 326","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-milarepa-i-have-forgot","title":"Accustomed Long to Love and Pity, a Song of Milarepa","by":"Milarepa","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1928,"trad":["buddhist"],"denom":["tibetan"],"type":"poem","occasion":["peace","daily","dying"],"text":"E’er since my Lord’s Grace entered in my mind,\nMy mind hath never strayed seeking various distractions.\n\nAccustomed long to contemplating Love and Pity,\nI have forgot all difference between myself and others.\n\nAccustomed, as I’ve been, to meditating on this life and the future life as one,\nI have forgot the dread of birth and death.\n\nAccustomed long to humbleness, of body and of mind,\nI have forgot the pride and haughty manner of the mighty.","note":"From a song Milarepa sang near the end of his life: long practice of love and kindness has worn away pride, fear, and the line between self and others.","voice":"brian","source":{"name":"Tibet’s Great Yogi Milarepa, ed. W. Y. Evans-Wentz (1928), p. 245 to 247","url":"https://archive.org/details/dli.ministry.06735"},"rights":"pd","pd":"published 1928; public domain in the United States since 2024"},{"id":"eastx-japji-all-virtues","title":"All Virtues Are Thine, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["daily","gratitude"],"text":"Pilgrimage, austerities, mercy, and almsgiving on general and special occasions\nWhosoever performeth, may obtain some little honour;\nBut he who heareth and obeyeth and loveth God in his heart,\nShall wash off his impurity in the place of pilgrimage within him.\nAll virtues are Thine, O Lord; none are mine.\nThere is no devotion without virtue.\nFrom the Self-existent proceeded Maya (athi), whence issued a word which produced Brahma and the rest:\n‘Thou art true. Thou art beautiful, there is ever pleasure in Thy heart!’\nWhat the time, what the epoch, what the lunar day, and what the week-day,\nWhat the season, and what the month when the world was created,\nThe Pandits did not discover; had they done so, they would have recorded it in the Purans.\nNor did the Qazis discover it; had they done so, they would have recorded it in the Quran:\nNeither the Jogi nor any other mortal knows the lunar day, or the week-day, or the season, or the month.\nOnly the Creator who fashioned the world knoweth when He did so.\nHow shall I address Thee, O God? how shall I praise Thee? how shall I describe Thee? and how shall I know Thee?\nSaith Nanak, everybody speaketh of Thee, one wiser than another.\nGreat is the Lord, great is His name; what He doeth cometh to pass.\nNanak, he who is proud shall not be honoured on his arrival in the next world.","note":"Pauri twenty one of the Japji: the pilgrimage that counts is the one within the heart, and only the Creator knows when the world began.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 206 to 207","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-rehras-servants-of-god","title":"O Servants of God, from Rehras","by":"Guru Ram Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","daily"],"text":"O servants of God and the true Guru, the true Being, offer this supplication unto Him.\nWe insects and worms seek thy protection, O true Guru; mercifully enlighten us with the Name;\nMy friend and divine Guru, enlighten me with God’s name.\nUnder the Guru’s instruction, the Name is the helper of my soul; singing God’s praises is my occupation.\nExceedingly fortunate are the men of God who have faith in Him and thirst for Him:\nOn obtaining the name of God, they are satisfied; when men meet the company of the saints, God’s attributes are known.\nThe saints who have obtained the society of the true Guru are those on whose foreheads it was so written from the beginning.\nBlest is that true society, Nanak, by meeting which the relish of God is obtained, and the Name manifested.","note":"A hymn of Guru Ram Das sung each evening in Rehras: blest is the company in which the sweetness of God is found.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 252 to 253","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sohila-one-sun","title":"As There Is One Sun and Many Seasons, from Sohila","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","peace","daily"],"text":"There are six schools of philosophy, six teachers, and six doctrines.\nThe Guru of gurus is but one, though He hath various forms.\nO father, preserve the system\nIn which the Creator is praised; that will redound to thy glory.\nAs there is one sun and many seasons,\nIn which there are wisas, chasas, gharis, pahars, lunar and week days, and months;\nSo, O Nanak, there is but one God, although His forms are many.","note":"The second hymn of Kirtan Sohila, sung at bedtime: as one sun makes many seasons, the one God takes many forms.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Sohila, p. 258 to 259","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-anand-true-love","title":"Without True Love, from the Anand","by":"Guru Amar Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["wedding","daily","gratitude"],"text":"Without true love man is unhonoured;\nMan is unhonoured without love. What can the wretched creature do?\nThere is none omnipotent but Thee; have mercy on me, O God.\nMan hath no other refuge than the Word, by attachment to which he is adorned.\nSaith Nanak, what can the wretched creature do without love?\n\nEvery one talketh of happiness, but true happiness can only be known from the Guru;\nIf the beloved Guru be merciful, happiness shall ever be known from him.\nThe Guru being merciful cut away my sins, and put into mine eyes the salve of divine knowledge;\nThe True One hath adorned with the Word those whose hearts have parted with worldly love.\nSaith Nanak, that is the real happiness which is known from the Guru.","note":"Pauris six and seven of the Anand, the Song of Joy: love is what gives life its honor, and true happiness is found through the Guru.","voice":"brian","source":{"name":"The Sikh Religion, vol. 2, tr. Max Arthur Macauliffe (1909), the Anand, p. 119","url":"https://archive.org/details/thesikhreligioni02macauoft"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-hearn-childrens-rhymes","title":"Japanese Lullaby and Children’s Rhymes","by":"Traditional Japanese","tr":"Lafcadio Hearn","year":1915,"trad":["shinto","buddhist","sbnr"],"type":"song","occasion":["birth","home","nature","evening"],"text":"Sleepy baby, sleep! Why are the honorable ears of the Child of the Hare of the honorable mountain so long? ’Tis because when he dwelt within her honored womb, his mamma ate the leaves of the loquat, the leaves of the bamboo-grass. That is why his honorable ears are so long.\n\nCome, firefly, I will give you water to drink. The water of that place is bitter; the water here is sweet.\n\nButterfly, little butterfly, light upon the na leaf. But if thou dost not like the na leaf, light, I pray thee, upon my hand.\n\nSnail, snail, put out your horns a little: it rains and the wind is blowing, so put out your horns, just for a little while.","note":"Old Japanese nursery verses gathered by Lafcadio Hearn: a lullaby about the little hare of the mountain, and little songs to the firefly, the butterfly, and the snail.","voice":"brian","source":{"name":"Japanese Lyrics, tr. Lafcadio Hearn (1915), Lullabies and Children’s Verse, p. 12 to 17","url":"https://archive.org/details/japaneselyrics00hearuoft"},"rights":"pd","pd":"published 1915; Hearn died 1904","denom":[]},{"id":"eastx-jain-true-sacrifice","title":"Penance Is My Fire, the Law Is My Pond, from the Uttaradhyayana Sutra","by":"Traditional, the Uttaradhyayana Sutra","tr":"Hermann Jacobi","year":1895,"trad":["jain"],"denom":["svetambara"],"type":"scripture","occasion":["daily","peace","forgiveness"],"text":"‘Where is your fire, your fireplace, your sacrificial ladle? where the dried cowdung (used as fuel)? Without these things, what kind of priests can the monks be? What oblations do you offer to the fire?’\n\n“Penance is my fire; life my fireplace; right exertion is my sacrificial ladle; the body the dried cowdung; Karman is my fuel; self-control, right exertion, and tranquillity are the oblations, praised by the sages, which I offer.”\n\n‘Where is your pond, and where the holy bathing-place? how do you make your ablutions or get rid of impurity? Tell us, O restrained monk whom the Yakshas hold in honour; we desire to learn it from you.’\n\n“The Law is my pond, celibacy my holy bathing-place, which is not turbid, and throughout clear for the soul; there I make ablutions; pure, clean, and thoroughly cooled I get rid of hatred (or impurity).”\n\n“The clever ones have discovered such bathing, it is the great bath praised by the seers, in which the great seers bathe, and, pure and clean, they obtain the highest place.”","note":"From the twelfth lecture of the Uttaradhyayana: a Jain monk tells priests of the inner sacrifice and the inner bath, where the soul is washed clear.","voice":"brian","source":{"name":"Gaina Sutras, part 2, tr. Hermann Jacobi, Sacred Books of the East vol. 45 (1895), Uttaradhyayana, Lecture 12, p. 55 to 56","url":"https://archive.org/details/dli.ernet.30488"},"rights":"pd","pd":"published 1895; Jacobi died 1937"},{"id":"eastx-chuangtzu-where-is-tao","title":"Where Is Tao?","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["nature","daily"],"text":"Tung Kuo Tzu asked Chuang Tzu, saying, “What you call Tao, where is it?”\n\n“There is nowhere,” replied Chuang Tzu, “where it is not.”\n\n“Tell me one place at any rate where it is,” said Tung Kuo Tzu.\n\n“It is in the ant,” replied Chuang Tzu.\n\n“Why go so low down?” asked Tung Kuo Tzu.\n\n“It is in a tare,” said Chuang Tzu.\n\n“Still lower,” objected Tung Kuo Tzu.\n\n“It is in a potsherd,” said Chuang Tzu.\n\n“Worse still!” cried Tung Kuo Tzu.\n\n“It is in ordure,” said Chuang Tzu. And Tung Kuo Tzu made no reply.\n\n“Sir,” continued Chuang Tzu, “your question does not touch the essential. When Huo, inspector of markets, asked the managing director about the fatness of pigs, the test was always made in parts least likely to be fat. Do not therefore insist in any particular direction; for there is nothing which escapes. Such is perfect Tao; and such also is ideal speech. Whole, entire, all, are three words which sound differently but mean the same. Their purport is One.”","note":"From chapter twenty two of Chuang Tzu: the Way is in everything, from the ant to the humblest thing on the ground.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 22, Knowledge Travels North, p. 285 to 286","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-hasid-musician","title":"Like a Musician and the Dancers","by":"Rabbi Nahman of Bratzlav, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["celebration","daily"],"text":"“We,” he once said to his Hassidim, “are like a musician who plays and the people around him are dancing, those who do not understand the beauty of the music cannot contain themselves for astonishment. Why are the people running after the musician, why are they dancing? And in the same way they cannot understand why you are running after me.”","note":"Rabbi Nahman’s gentle answer to his critics: those who hear the music understand why the people dance.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 89","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-hasid-souls-united","title":"Our Souls Are United All the Time","by":"Rabbi Nahman of Bratzlav, as told by S. A. Horodezky","tr":"Maria Horodezky-Magasanik","year":1928,"trad":["jewish"],"denom":["hasidic","orthodox"],"type":"reflection","occasion":["grief","comfort","home"],"text":"And the “Master,” Rabbi Nahman, received them all with great love. He knew how to hold their hearts. He treated them as a father his dearly beloved children. He held himself the equal of his Hassidim, not their master, as did most of the Zaddikim. “Each one of you,” he once said to his Hassidim, “has a place in my heart.” On another occasion Rabbi Nahman wrote to his Hassidim while away on a journey: “We are indeed separated from each other, but our souls are united all the time.” “Every one of you is a partner in my doctrine,” he said.","note":"Rabbi Nahman, who treated his followers as a father treats dearly loved children, wrote to them while far away: our souls are united all the time.","voice":"brian","source":{"name":"Leaders of Hassidism, S. A. Horodezky, tr. Maria Horodezky-Magasanik (1928), p. 90 to 91","url":"https://archive.org/details/MN40141ucmf_10"},"rights":"pd","pd":"published 1928 (London); public domain in the United States since 2024"},{"id":"eastx-subhasita-sutta","title":"Well-Spoken Words, the Subhasita Sutta","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["daily","wedding","peace"],"text":"‘Well-spoken language the just call the principal (thing); let one speak what is right (dhamma), not what is unrighteous (adhamma), that is the second; let one speak what is pleasing, not what is unpleasing, that is the third; let one speak what is true, not what is false, that is the fourth.’\n\n‘Let one say such words by which he does not pain himself, nor hurt others; such words are truly well-spoken.\n\n‘Let one speak pleasing words which are received joyfully (by all), and which (saying) he, without committing sins, speaks what is pleasing to others.\n\n‘Truth verily is immortal speech, this is a true saying; in what is true, in what is good, and in what is right, the just stand firm, so they say.’","note":"From the Sutta Nipata, on right speech: let us speak words that are kind, received with joy, and true.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Subhasitasutta, p. 72 to 73","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-zor-good-waters","title":"Unto the Good Waters, from the Aban Yasht","by":"Traditional, the Avesta","tr":"James Darmesteter","year":1883,"trad":["zoroastrian"],"type":"prayer","occasion":["birth","nature","healing","blessing"],"text":"Unto the good Waters, made by Mazda; unto the holy water-spring Ardvi Anahita; unto all waters, made by Mazda; unto all plants, made by Mazda, Be propitiation, with sacrifice, prayer, propitiation, and glorification.\n\nAhura Mazda spake unto Spitama Zarathustra, saying: ‘Offer up a sacrifice, O Spitama Zarathustra! unto this spring of mine, Ardvi Sura Anahita, the wide-expanding and health-giving, who hates the Daevas and obeys the laws of Ahura, who is worthy of sacrifice in the material world, worthy of prayer in the material world; the life-increasing and holy, the herd-increasing and holy, the fold-increasing and holy, the wealth-increasing and holy, the country-increasing and holy;\n\n‘Who makes the seed of all males pure, who makes the womb of all females pure for bringing forth, who makes all females bring forth in safety, who puts milk into the breasts of all females in the right measure and the right quality;\n\n‘The large river, known afar, that is as large as the whole of the waters that run along the earth; that runs powerfully from the height Hukairya down to the sea Vouru-Kasha.’","note":"From the hymn to the waters and the holy spring Ardvi Sura Anahita, who gives health and helps every mother bring forth her child in safety. Said beside water and in prayers for a safe birth.","voice":"brian","source":{"name":"The Zend-Avesta, part 2, tr. James Darmesteter, Sacred Books of the East vol. 23 (1883), Aban Yasht 5, p. 53 to 54","url":"https://archive.org/details/wg923"},"rights":"pd","pd":"published 1883; Darmesteter died 1894","denom":[]},{"id":"eastx-chuangtzu-wheelwright","title":"The Wheelwright and the Duke","by":"Chuang Tzu","tr":"Herbert A. Giles","year":1889,"trad":["taoist"],"type":"story","occasion":["daily"],"text":"Duke Huan was one day reading in his hall, when a wheelwright who was working below, flung down his hammer and chisel, and mounting the steps said, “What words may your Highness be studying?”\n\n“I am studying the words of the Sages,” replied the Duke.\n\n“Are the Sages alive?” asked the wheelwright.\n\n“No,” answered the Duke; “they are dead.”\n\n“Then the words your Highness is studying,” rejoined the wheelwright, “are only the dregs of the ancients.”\n\n“What do you mean, sirrah!” cried the Duke, “by interfering with what I read? Explain yourself, or you shall die.”\n\n“Let me take an illustration,” said the wheelwright, “from my own trade. In making a wheel, if you work too slowly, you can't make it firm; if you work too fast, the spokes won't fit in. You must go neither too slowly nor too fast. There must be co-ordination of mind and hand. Words cannot explain what it is, but there is some mysterious art herein. I cannot teach it to my son; nor can he learn it from me. Consequently, though seventy years of age, I am still making wheels in my old age. If the ancients, together with what they could not impart, are dead and gone, then what your Highness is studying must be the dregs.”","note":"From chapter thirteen of Chuang Tzu: an old wheelwright teaches a duke that the deepest skill lives in the hands and heart, beyond what words can hold.","voice":"brian","source":{"name":"Chuang Tzu: Mystic, Moralist, and Social Reformer, tr. Herbert A. Giles (1889), chapter 13, The Tao of God, p. 171 to 172","url":"https://archive.org/details/chuangtzumysticm00chua"},"rights":"pd","pd":"published 1889; Giles died 1935","denom":[]},{"id":"eastx-hiri-sutta-friendship","title":"A Friend Who Cannot Be Severed, the Hiri Sutta","by":"Traditional, the Sutta Nipata","tr":"V. Fausboll","year":1881,"trad":["buddhist"],"denom":["theravada"],"type":"scripture","occasion":["daily","wedding","celebration"],"text":"He who transgresses and despises modesty, who says, ‘I am a friend,’ but does not undertake any work that can be done, know (about) him: ‘he is not my (friend).’\n\nWhosoever uses pleasing words to friends without effect, him the wise know as one that (only) talks, but does not do anything.\n\nHe is not a friend who always eagerly suspects a breach and looks out for faults; but he with whom he dwells as a son at the breast (of his mother), he is indeed a friend that cannot be severed (from him) by others.\n\nHe who hopes for fruit, cultivates the energy that produces joy and the pleasure that brings praise, (while) carrying the human yoke.\n\nHaving tasted the sweetness of seclusion and tranquillity one becomes free from fear and free from sin, drinking in the sweetness of the Dhamma.","note":"From the Sutta Nipata, on true friendship: a real friend is one with whom we dwell as safely as a child at its mother’s breast.","voice":"brian","source":{"name":"The Sutta-Nipata, tr. V. Fausboll, Sacred Books of the East vol. 10, part 2 (1881), Hirisutta, p. 42 to 43","url":"https://archive.org/details/wg910"},"rights":"pd","pd":"published 1881; Fausboll died 1908"},{"id":"eastx-japji-priceless","title":"Priceless Are Thine Attributes, from the Japji","by":"Guru Nanak","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["gratitude","daily","celebration"],"text":"Priceless are Thine attributes, O God, and priceless Thy dealings;\nPriceless Thy dealers, priceless Thy storehouses;\nPriceless what cometh from Thee, and priceless what is taken away;\nPriceless Thy rate and priceless the time for dealing;\nPriceless Thy justice and priceless Thy court;\nPriceless Thy weights and priceless Thy measures;\nPriceless Thy gifts and priceless Thy marks;\nPriceless Thy mercy and priceless Thine ordinances.\nHow beyond all price Thou art cannot be stated.\nEver speaking of Thee men continue to fix their thoughts on Thee.\n\nThey who read the Veds and Purans speak of Thee;\nLearned men speak of Thee and deliver discourses on Thee;\nBrahmas speak of Thee, and Indars speak of Thee;\nThe milkmaids and Krishan speak of Thee;\nShivs speak of Thee, the Sidhs speak of Thee;\nAll the Budhas Thou hast created speak of Thee;\nThe demons speak of Thee, the gods speak of Thee;\nThy demigods, men, munis, and servants speak of Thee;\nHow many speak of Thee or attempt to speak of Thee!\nHow many depart while speaking of Thee!\nIf Thou wert to create as many more as Thou hast created,\nEven then few of them would be able to speak adequately of Thee.\nThou mayest be as great as Thou pleasest.\nNanak, only the True One Himself knoweth how great He is.","note":"Pauri twenty six of the Japji: everything that comes from God is priceless, and all creation speaks of God.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Japji, p. 209 to 210","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-bardo-path-of-good-wishes","title":"Lead Us Along the Path, from the Path of Good Wishes","by":"Traditional, the Bardo Thodol","tr":"Lama Kazi Dawa-Samdup and W. Y. Evans-Wentz","year":1927,"trad":["buddhist"],"denom":["tibetan","mahayana"],"type":"litany","occasion":["dying","funeral","comfort"],"text":"O ye Conquerors and your Sons, abiding in the Ten Directions,\nO ye ocean-like Congregation of the All-Good Conquerors, the Peaceful and the Wrathful,\nO ye Gurus and Devas, and ye Dakinis, the Faithful Ones,\nHearken now out of [your] great love and compassion:\nObeisance, O ye assemblage of Gurus and Dakinis;\nOut of your great love, lead us along the Path.\n\nWhen, through illusion, I and others are wandering in the Sangsara,\nAlong the bright light-path of undistracted listening, reflection, and meditation,\nMay the Gurus of the Inspired Line lead us,\nMay the bands of Mothers be our rear-guard,\nMay we be saved from the fearful narrow passage-way of the Bardo,\nMay we be placed in the state of the perfect Buddhahood.\n\nWhen, through great attachment, [we are] wandering in the Sangsara,\nAlong the bright light-path of the Discriminating Wisdom,\nMay the Bhagavan Amitabha lead us,\nMay the Mother, [She]-of-White-Raiment, be our rear-guard,\nMay we be saved from the fearful narrow passage-way of the Bardo,\nMay we be placed in the state of the perfect Buddhahood.","note":"From the Appendix of the Tibetan Book of the Dead, a prayer said for and with the dying: may the wise and loving ones lead us along the bright path and through every narrow passage.","voice":"brian","source":{"name":"The Tibetan Book of the Dead, ed. W. Y. Evans-Wentz (1927), p. 199 to 200","url":"https://archive.org/details/the-tibetan-book-of-the-dead_202401"},"rights":"pd","pd":"published 1927 (first edition, Oxford University Press); public domain in the United States since 2023"},{"id":"eastx-rehras-thou-art-ocean","title":"Thou Art an Ocean, from Rehras","by":"Guru Ram Das","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["evening","comfort","peace"],"text":"Thou art the true Creator, my Lord.\nWhat pleaseth Thee shall come to pass; what Thou givest I shall receive.\nEverything is Thine: all meditate on Thee.\nThey to whom Thou showest kindness, obtain the jewel of Thy name.\nThe pious have gained, and the perverse have lost it.\nThou Thyself hast separated these and blended those with Thee.\nThou art an ocean: all are contained in Thee.\nThere is none beside Thee.\nAll living creatures are Thy play.\nWhen Thou didst desire separation, they who had met Thee were separated from Thee; when Thou didst desire union, Thou didst blend them with Thyself.\nThat saint whom Thou causest to know Thee shall know Thee,\nAnd ever dwell on Thy praises.\nThey who have served God have found happiness,\nAnd have become easily absorbed in His name.\nThou Thyself art the Creator; everything that is made is Thine;\nThere is none beside Thee;\nThou beholdest and knowest Thy handiwork.\nThe slave Nanak saith, under the Guru’s instruction Thou becomest manifest.","note":"A hymn of Guru Ram Das from Rehras, the sunset prayer: Thou art an ocean, and all are contained in Thee.","voice":"brian","source":{"name":"The Sikh Religion, vol. 1, tr. Max Arthur Macauliffe (1909), Rahiras, p. 256","url":"https://archive.org/details/in.ernet.dli.2015.85504"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-barah-maha-opening","title":"O God, Mercifully Unite, the Opening of the Barah Maha","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"hymn","occasion":["comfort","season","grief"],"text":"O God, mercifully unite with Thee those who by their past acts are separated from Thee!\nWeary of wandering in the four corners of the world and in every direction, we have come to Thy protection.\nA cow without milk is of no avail:\nWithout water the tree withereth and beareth no fruit.\nIf we meet not the Lord God, the Friend, how shall we find rest?\nThe city or village or house where God is not seen is as a furnace.\nAll decorations, betel, and tasteful viands are unstable together with the body.\nWithout the Lord God all friends are as the god of death.\nNanak's supplication is, ‘Mercifully grant me Thy name;\nO Lord God, whose abode is immovable, unite me with Thee.’","note":"The opening verse of Guru Arjan’s Barah Maha, the Twelve Months: as a tree longs for water, the heart longs for the Beloved.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), The Twelve Months of Guru Arjan (Barah Maha, Majh), p. 124","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]},{"id":"eastx-sukhmani-no-place-where-he-is-not","title":"There Is No Place Where He Is Not, from the Sukhmani","by":"Guru Arjan","tr":"Max Arthur Macauliffe","year":1909,"trad":["sikh"],"type":"scripture","occasion":["nature","comfort","peace"],"text":"In the company of the saints I have seen God within me;\nGod's name to me is sweet;\nAll things of various colours and divers forms\nAre in the heart of the one God.\nGod's name is the nine treasures and ambrosia\nFor him in whose body it findeth a resting-place.\nWhere there is deep meditation, the unbeaten sound is heard;\nThe wonder and marvel of it cannot be described.\nHe to whom God showeth Himself, beholdeth Him,\nAnd, O Nanak, obtaineth understanding.\n\nThe Endless One is with thee whether at home or abroad;\nHe is contained in every heart,\nIn earth, heaven, and nether regions;\nIn all worlds He is the Perfect Cherisher;\nIn forest, glade, and mountain He is the Supreme Being;\nAs He ordereth so are His creatures' acts.\nIn wind, water, fire,\nAnd in every direction is He contained;\nThere is no place where He is not.\nNanak, by the Guru's favour obtain happiness.","note":"From the twenty third ashtapadi of the Sukhmani: the Endless One is with us at home and abroad, in forest, glade, and mountain.","voice":"brian","source":{"name":"The Sikh Religion, vol. 3, tr. Max Arthur Macauliffe (1909), Sukhmani, p. 266","url":"https://archive.org/details/sikhreligionvoli029633mbp"},"rights":"pd","pd":"published 1909; Macauliffe died 1913","denom":[]}];
